import requests
import json
from typing import Dict, List, Any

class GoogleVisionAsyncClient:
    """Client for Google Cloud Vision API asynchronous operations"""

    def __init__(self, api_key: str = "YOUR_API_KEY", project_id: str = "YOUR_PROJECT_ID"):
        self.api_key = api_key
        self.project_id = project_id
        self.base_url = "https://vision.googleapis.com/v1"
        self.headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json"
        }

    def start_async_image_analysis(
        self,
        image_uris: List[str],
        output_gcs_uri: str,
        features: List[Dict[str, Any]] = None,
        location: str = "us-central1",
        batch_size: int = 10
    ) -> Dict[str, Any]:
        """
        Start a long-running image analysis job that writes results to GCS.

        Args:
            image_uris: List of GCS URIs for images (e.g., ["gs://bucket/image1.jpg"])
            output_gcs_uri: GCS destination for results (e.g., "gs://output-bucket/results/")
            features: List of features to detect. Defaults to label and face detection.
            location: GCS location (default: us-central1)
            batch_size: Number of responses per output file

        Returns:
            Operation response with operation name for tracking
        """
        if features is None:
            features = [
                {"type": "LABEL_DETECTION", "max_results": 10},
                {"type": "FACE_DETECTION"},
                {"type": "OBJECT_LOCALIZATION"}
            ]

        # Build requests for each image
        requests = []
        for image_uri in image_uris:
            requests.append({
                "image": {
                    "source": {
                        "gcs_image_uri": image_uri
                    }
                },
                "features": features
            })

        # Build the async batch request
        payload = {
            "requests": requests,
            "output_config": {
                "gcs_destination": {
                    "uri": output_gcs_uri
                },
                "batch_size": batch_size
            },
            "parent": f"projects/{self.project_id}/locations/{location}"
        }

        endpoint = f"{self.base_url}/images:asyncBatchAnnotate"
        response = requests.post(endpoint, headers=self.headers, json=payload)
        response.raise_for_status()

        return response.json()

    def start_async_document_analysis(
        self,
        document_uris: List[Dict[str, str]],
        output_gcs_uri: str,
        features: List[Dict[str, Any]] = None,
        location: str = "us-central1",
        batch_size: int = 2
    ) -> Dict[str, Any]:
        """
        Start an asynchronous document analysis job for large-scale multi-page file processing.

        Args:
            document_uris: List of dicts with 'uri' and 'mime_type' keys
                          e.g., [{"uri": "gs://bucket/doc.pdf", "mime_type": "application/pdf"}]
            output_gcs_uri: GCS destination for results (e.g., "gs://output-bucket/doc-results/")
            features: List of features to detect. Defaults to document text detection.
            location: GCS location (default: us-central1)
            batch_size: Number of responses per output file

        Returns:
            Operation response with operation name for tracking
        """
        if features is None:
            features = [
                {"type": "DOCUMENT_TEXT_DETECTION"}
            ]

        # Build requests for each document
        requests = []
        for doc in document_uris:
            requests.append({
                "input_config": {
                    "gcs_source": {
                        "uri": doc["uri"]
                    },
                    "mime_type": doc["mime_type"]
                },
                "features": features,
                "output_config": {
                    "gcs_destination": {
                        "uri": output_gcs_uri
                    },
                    "batch_size": batch_size
                }
            })

        # Build the async batch request
        payload = {
            "requests": requests,
            "parent": f"projects/{self.project_id}/locations/{location}"
        }

        endpoint = f"{self.base_url}/files:asyncBatchAnnotate"
        response = requests.post(endpoint, headers=self.headers, json=payload)
        response.raise_for_status()

        return response.json()

    def check_operation_status(self, operation_name: str) -> Dict[str, Any]:
        """
        Check the status of a long-running operation.

        Args:
            operation_name: The operation name from the initial response

        Returns:
            Operation status and results if complete
        """
        endpoint = f"{self.base_url}/{operation_name}"
        response = requests.get(endpoint, headers=self.headers)
        response.raise_for_status()

        return response.json()


# Example usage
if __name__ == "__main__":
    # Initialize client with your credentials
    client = GoogleVisionAsyncClient(
        api_key="YOUR_API_KEY",
        project_id="YOUR_PROJECT_ID"
    )

    # Task 1: Kick off long-running image analysis job
    print("Starting async image analysis job...")
    image_operation = client.start_async_image_analysis(
        image_uris=[
            "gs://my-bucket/images/photo1.jpg",
            "gs://my-bucket/images/photo2.jpg",
            "gs://my-bucket/images/photo3.jpg"
        ],
        output_gcs_uri="gs://my-output-bucket/image-analysis-results/",
        features=[
            {"type": "LABEL_DETECTION", "max_results": 20},
            {"type": "FACE_DETECTION"},
            {"type": "SAFE_SEARCH_DETECTION"},
