        batch_size=10
    )

    print(f"Image analysis job started: {image_operation.get('name')}")
    print(f"Full response: {json.dumps(image_operation, indent=2)}")

    # Task 2: Separately start async document analysis job
    print("\nStarting async document analysis job...")
    document_operation = client.start_async_document_analysis(
        document_uris=[
            {
                "uri": "gs://my-bucket/documents/contract.pdf",
                "mime_type": "application/pdf"
            },
            {
                "uri": "gs://my-bucket/documents/report.pdf",
                "mime_type": "application/pdf"
            }
        ],
