        features=[
            {"type": "DOCUMENT_TEXT_DETECTION"}
        ],
        batch_size=2
    )

    print(f"Document analysis job started: {document_operation.get('name')}")
    print(f"Full response: {json.dumps(document_operation, indent=2)}")

