from typing import Optional, Dict, Any

class SaleorAPIClient:
    """Client for interacting with Saleor GraphQL API"""

    def __init__(self, base_url: str, api_token: str = None):
        """
        Initialize the Saleor API client

        Args:
            base_url: Base URL of the Saleor instance (e.g., 'https://example.saleor.cloud')
            api_token: API authentication token (optional, use 'YOUR_API_KEY' as placeholder)
        """
        self.base_url = base_url.rstrip('/')
        self.graphql_endpoint = f"{self.base_url}/graphql"
        self.headers = {
            'Content-Type': 'application/json',
        }
        if api_token:
            self.headers['Authorization'] = f'Bearer {api_token}'

    def _execute_query(self, query: str, variables: Dict[str, Any] = None) -> Dict[str, Any]:
        """
        Execute a GraphQL query

        Args:
            query: GraphQL query string
            variables: Query variables

        Returns:
            Response data dictionary
        """
        payload = {
            'query': query,
            'variables': variables or {}
        }

        response = requests.post(
            self.graphql_endpoint,
            headers=self.headers,
            json=payload
        )
        response.raise_for_status()
        return response.json()

    def get_product(self, 
                   product_id: Optional[str] = None, 
                   slug: Optional[str] = None,
                   channel: str = 'default-channel') -> Dict[str, Any]:
        """
        Get product details by ID or slug

        Args:
            product_id: Product ID (optional)
            slug: Product slug/URL-friendly name (optional)
            channel: Channel slug (default: 'default-channel')

        Returns:
            Product details dictionary
        """
        query = """
        query GetProduct($id: ID, $slug: String, $channel: String) {
          product(id: $id, slug: $slug, channel: $channel) {
            id
            name
            slug
            description
            seoTitle
            seoDescription
            category {
              id
              name
              slug
            }
            productType {
              name
            }
            defaultVariant {
              id
              name
              sku
              pricing {
                price {
                  gross {
                    amount
                    currency
                  }
                }
              }
            }
            variants {
              id
              name
              sku
            }
            pricing {
              priceRange {
                start {
                  gross {
                    amount
                    currency
                  }
                }
                stop {
                  gross {
                    amount
                    currency
                  }
                }
              }
            }
            thumbnail {
              url
            }
            isAvailableForPurchase
            availableForPurchaseAt
            created
            updatedAt
          }
        }
        """

        variables = {'channel': channel}
        if product_id:
            variables['id'] = product_id
        if slug:
            variables['slug'] = slug

        result = self._execute_query(query, variables)
        return result.get('data', {}).get('product')

    def get_order(self,
                 order_id: Optional[str] = None,
                 external_reference: Optional[str] = None) -> Dict[str, Any]:
