import requests
import json
from datetime import datetime

class FirestoreTransactionClient:
    """Client for performing atomic Firestore operations using transactions."""

    def __init__(self, project_id, database_id="(default)", api_key="YOUR_API_KEY"):
        """
        Initialize the Firestore client.

        Args:
            project_id: Google Cloud project ID
            database_id: Firestore database ID (default is "(default)")
            api_key: Google Cloud API key for authentication
        """
        self.project_id = project_id
        self.database_id = database_id
        self.api_key = api_key
        self.base_url = "https://firestore.googleapis.com/v1"
        self.database_path = f"projects/{project_id}/databases/{database_id}"

    def _get_headers(self):
        """Get headers for API requests."""
        return {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {self.api_key}"
        }

    def begin_transaction(self):
        """
        Begin a new read-write transaction.

        Returns:
            bytes: Transaction ID to use in subsequent operations
        """
        url = f"{self.base_url}/{self.database_path}/documents:beginTransaction"

        payload = {
            "options": {
                "readWrite": {}
            }
        }

        response = requests.post(
            url,
            headers=self._get_headers(),
            json=payload
        )
        response.raise_for_status()

        result = response.json()
        return result.get("transaction")

    def create_document_write(self, collection_id, document_id, fields):
        """
        Create a Write operation for adding a document.

        Args:
            collection_id: The collection to add the document to
            document_id: The document ID to use
            fields: Dictionary of field names to values

        Returns:
            dict: Write operation object
        """
        # Convert Python dict to Firestore field format
        firestore_fields = {}
        for field_name, field_value in fields.items():
            if isinstance(field_value, str):
                firestore_fields[field_name] = {"stringValue": field_value}
            elif isinstance(field_value, int):
                firestore_fields[field_name] = {"integerValue": str(field_value)}
            elif isinstance(field_value, float):
                firestore_fields[field_name] = {"doubleValue": field_value}
            elif isinstance(field_value, bool):
                firestore_fields[field_name] = {"booleanValue": field_value}
            elif field_value is None:
                firestore_fields[field_name] = {"nullValue": None}
            else:
                # Default to string representation
                firestore_fields[field_name] = {"stringValue": str(field_value)}

        document_path = f"{self.database_path}/documents/{collection_id}/{document_id}"

        return {
            "update": {
                "name": document_path,
                "fields": firestore_fields
            }
        }

    def commit_transaction(self, transaction_id, writes):
        """
        Commit a transaction with the specified write operations.

        Args:
            transaction_id: Transaction ID from begin_transaction()
            writes: List of Write operation objects

        Returns:
            dict: Commit response with write results and commit time
        """
        url = f"{self.base_url}/{self.database_path}/documents:commit"

        payload = {
            "transaction": transaction_id,
            "writes": writes
        }

        response = requests.post(
            url,
            headers=self._get_headers(),
            json=payload
        )
        response.raise_for_status()

        return response.json()

    def add_document_atomically(self, collection_id, document_id, fields, 
                               additional_writes=None):
        """
        Add a new document to a collection atomically within a transaction.

        This method demonstrates the full workflow:
        1. Begin a transaction
        2. Create write operations (including the new document)
        3. Commit all writes atomically

        Args:
            collection_id: The collection to add the document to
            document_id: The document ID to use
            fields: Dictionary of field names to values for the new document
            additional_writes: Optional list of additional Write operations

        Returns:
            dict: Commit response with results
        """
        # Step 1: Begin transaction
        print(f"Beginning transaction...")
        transaction_id = self.begin_transaction()
        print(f"Transaction started: {transaction_id[:20]}...")

        # Step 2: Create write operations
        writes = []

        # Add the main document write
        main_write = self.create_document_write(collection_id, document_id, fields)
        writes.append(main_write)
        print(f"Created write operation for document: {collection_id}/{document_id}")

        # Add any additional writes
        if additional_writes:
            writes.extend(additional_writes)
            print(f"Added {len(additional_writes)} additional write operations")

        # Step 3: Commit transaction atomically
        print(f"Committing {len(writes)} write operation(s) atomically...")
        result = self.commit_transaction(transaction_id, writes)
        print(f"Transaction committed successfully at {result.get('commitTime')}")

        return result


def main():
    """Example usage demonstrating atomic document creation."""

    # Initialize client with your credentials
    client = FirestoreTransactionClient(
        project_id="my-project-id",
        database_id="(default)",
        api_key="YOUR_API_KEY"
    )

    # Define the document to add
    collection_id = "users"
    document_id = "user123"

    document_fields = {
        "name": "John Doe",
        "email": "john.doe@example.com",
        "age": 30,
