        )

        print("\n=== Transaction Complete ===")
        print(f"Number of writes committed: {len(result.get('writeResults', []))}")
        print(f"Commit time: {result.get('commitTime')}")

        for idx, write_result in enumerate(result.get('writeResults', [])):
            print(f"Write {idx + 1} update time: {write_result.get('updateTime')}")

    except requests.exceptions.HTTPError as e:
        print(f"Error: {e}")
        print(f"Response: {e.response.text}")


if __name__ == "__main__":
    main()
```

