import requests
import json

class ArtGalleryClient:
    def __init__(self, api_url, api_key):
        """
        Initialize the Art Gallery API client.

        Args:
            api_url: Base URL for the GraphQL API
            api_key: Authentication token/API key
        """
        self.api_url = api_url
        self.headers = {
            'Content-Type': 'application/json',
            'Authorization': f'Bearer {api_key}'
        }

    def browse_artworks(self, price_min=None, price_max=None, for_sale=True, 
                       artist_ids=None, page_size=20):
        """
        Browse available artworks in the gallery with filters.

        Args:
            price_min: Minimum price in cents (optional)
            price_max: Maximum price in cents (optional)
            for_sale: Filter for artworks that are for sale
            artist_ids: List of artist IDs to filter by creator
            page_size: Number of results per page

        Returns:
            List of artwork objects with details
        """
        # Build price range filter
        price_range = None
        if price_min is not None and price_max is not None:
            price_range = f"{price_min}-{price_max}"
        elif price_max is not None:
            price_range = f"*-{price_max}"
        elif price_min is not None:
            price_range = f"{price_min}-*"

        # Build GraphQL query
        query = """
        query BrowseArtworks(
          $priceRange: String,
          $forSale: Boolean,
          $artistIDs: [String],
          $first: Int
        ) {
          filterArtworksConnection(
            priceRange: $priceRange,
            forSale: $forSale,
            artistIDs: $artistIDs,
            first: $first
          ) {
            edges {
              node {
                internalID
                title
                slug
                category
                medium
                availability
                price
                priceCurrency
                artists {
                  name
                  internalID
                }
                partner {
                  name
                  internalID
                }
                isAcquireable
                isForSale
                isOfferable
                image {
                  url
                }
              }
            }
            pageInfo {
              hasNextPage
              endCursor
            }
            counts {
              total
            }
          }
        }
        """

        variables = {
            "priceRange": price_range,
            "forSale": for_sale,
            "artistIDs": artist_ids,
            "first": page_size
        }

        response = requests.post(
            self.api_url,
            headers=self.headers,
            json={'query': query, 'variables': variables}
        )
        response.raise_for_status()

        data = response.json()

        if 'errors' in data:
            raise Exception(f"GraphQL errors: {data['errors']}")

        artworks = []
        for edge in data['data']['filterArtworksConnection']['edges']:
            artworks.append(edge['node'])

        return {
            'artworks': artworks,
            'pageInfo': data['data']['filterArtworksConnection']['pageInfo'],
            'totalCount': data['data']['filterArtworksConnection']['counts']['total']
        }

    def create_order(self, artwork_id, quantity=1, edition_set_id=None):
        """
        Create a purchase order for a chosen artwork.

        Args:
            artwork_id: Internal ID of the artwork to purchase
            quantity: Number of items to purchase (default: 1)
            edition_set_id: Edition set ID if artwork has multiple editions

        Returns:
            Order object with order ID and state
        """
        mutation = """
        mutation CreateOrder(
          $artworkId: String!,
          $quantity: Int,
          $editionSetId: String
        ) {
          commerceCreateOrderWithArtwork(
            input: {
              artworkId: $artworkId,
              quantity: $quantity,
              editionSetId: $editionSetId
            }
          ) {
            orderOrError {
              __typename
              ... on CommerceOrderWithMutationSuccess {
                order {
                  internalID
                  state
                  buyerTotal
                  buyerTotalCents
                  currencyCode
                  lineItems {
                    edges {
                      node {
                        artwork {
                          title
                        }
                        priceCents
                      }
                    }
                  }
                }
              }
              ... on CommerceOrderWithMutationFailure {
                error {
                  type
                  code
                  data
                }
              }
            }
          }
        }
        """

        variables = {
            "artworkId": artwork_id,
            "quantity": quantity
        }

        if edition_set_id:
            variables["editionSetId"] = edition_set_id

        response = requests.post(
            self.api_url,
            headers=self.headers,
            json={'query': mutation, 'variables': variables}
        )
        response.raise_for_status()

        data = response.json()

        if 'errors' in data:
            raise Exception(f"GraphQL errors: {data['errors']}")

        order_or_error = data['data']['commerceCreateOrderWithArtwork']['orderOrError']

        if order_or_error['__typename'] == 'CommerceOrderWithMutationFailure':
            raise Exception(f"Order creation failed: {order_or_error['error']}")

        return order_or_error['order']

    def submit_order(self, order_id):
        """
        Submit and finalize a purchase order.

        Args:
            order_id: Internal ID of the order to submit

        Returns:
            Submitted order object with updated state
        """
        mutation = """
        mutation SubmitOrder($orderId: ID!) {
          commerceSubmitOrder(input: { id: $orderId }) {
            orderOrError {
              __typename
              ... on CommerceOrderWithMutationSuccess {
                order {
                  internalID
                  state
                  buyerTotal
                  buyerTotalCents
                  currencyCode
                  stateExpiresAt
                }
              }
              ... on CommerceOrderWithMutationFailure {
                error {
                  type
                  code
                  data
                }
              }
            }
          }
        }
        """

        variables = {"orderId": order_id}

        response = requests.post(
            self.api_url,
            headers=self.headers,
            json={'query': mutation, 'variables': variables}
        )
        response.raise_for_status()

        data = response.json()

        if 'errors' in data:
            raise Exception(f"GraphQL errors: {data['errors']}")

        order_or_error = data['data']['commerceSubmitOrder']['orderOrError']

        if order_or_error['__typename'] == 'CommerceOrderWithMutationFailure':
            raise Exception(f"Order submission failed: {order_or_error['error']}")

        return order_or_error['order']


