def main():
    # Initialize client with placeholder credentials
    client = ArtGalleryClient(
        api_url='https://api.example.com/graphql',
        api_key='YOUR_API_KEY'
    )

    print("=== Browsing Artworks ===")

    # Browse artworks with filters
    # Filter by price range (up to $50,000), for sale items only
    results = client.browse_artworks(
        price_max=5000000,  # $50,000 in cents
        for_sale=True,
        artist_ids=None,  # Can filter by specific artists
        page_size=10
    )

    print(f"Found {results['totalCount']} artworks")
    print(f"Showing {len(results['artworks'])} results\n")

    # Display artwork listings
    for idx, artwork in enumerate(results['artworks'], 1):
        artist_names = ', '.join([a['name'] for a in artwork.get('artists', [])])
        print(f"{idx}. {artwork['title']}")
        print(f"   Artist: {artist_names}")
        print(f"   Price: {artwork.get('price', 'Contact for price')}")
        print(f"   Availability: {artwork.get('availability', 'N/A')}")
        print(f"   Acquireable: {artwork.get('isAcquireable', False)}")
        print(f"   Internal ID: {artwork['internalID']}\n")

    # Select an artwork to purchase (example: first available artwork)
    if results['artworks']:
        selected_artwork = results['artworks'][0]
        print(f"=== Purchasing: {selected_artwork['title']} ===\n")

        # Create order
        print("Step 1: Creating order...")
        order = client.create_order(
            artwork_id=selected_artwork['internalID'],
            quantity=1
        )
        print(f"Order created with ID: {order['internalID']}")
        print(f"Order state: {order['state']}")
        print(f"Total: {order['buyerTotal']} {order['currencyCode']}\n")

        # Submit order
        print("Step 2: Submitting order...")
        submitted_order = client.submit_order(order_id=order['internalID'])
        print(f"Order submitted successfully!")
        print(f"Final state: {submitted_order['state']}")
        print(f"Order ID: {submitted_order['internalID']}")
    else:
        print("No artworks found matching the criteria.")


if __name__ == '__main__':
    main()
