        query SearchLegacy($host: str!, $index: JSON!, $body: JSON!, $size: num, $from: num) {
          elastic56(host: $host) {
            search(index: $index, body: $body, size: $size, from: $from)
          }
        }
        """

        variables = {
            "host": host,
            "index": index,
            "body": query_body,
            "size": size,
            "from": from_offset
        }

        response = self.session.post(
