```python
import base64
import json
from pathlib import Path
from typing import List, Dict, Any
import requests

class VisionAPIClient:
    """Client for Google Cloud Vision API image and document analysis."""

    def __init__(self, api_key: str):
        self.api_key = api_key
        self.base_url = "https://vision.googleapis.com/v1"

    def encode_file(self, file_path: str) -> str:
        """Encode file to base64 string."""
        with open(file_path, 'rb') as f:
            return base64.b64encode(f.read()).decode('utf-8')

    def analyze_images(self, image_paths: List[str]) -> Dict[str, Any]:
        """
        Analyze multiple images for labels, text, and objects.

        Args:
            image_paths: List of paths to image files

        Returns:
            Dictionary containing analysis results for all images
        """
        requests_list = []

        for img_path in image_paths:
            encoded_image = self.encode_file(img_path)
            requests_list.append({
                "image": {"content": encoded_image},
                "features": [
                    {"type": "LABEL_DETECTION", "maxResults": 10},
                    {"type": "TEXT_DETECTION"},
                    {"type": "OBJECT_LOCALIZATION", "maxResults": 10}
                ]
            })

        payload = {"requests": requests_list}

        response = requests.post(
            f"{self.base_url}/images:annotate?key={self.api_key}",
            headers={"Content-Type": "application/json"},
            json=payload
        )

        response.raise_for_status()
        return response.json()

    def analyze_pdf(self, pdf_path: str, pages: List[int] = None) -> Dict[str, Any]:
        """
        Analyze PDF document for text detection.

        Args:
            pdf_path: Path to PDF file
            pages: List of page numbers to analyze (1-indexed), or None for all pages

        Returns:
            Dictionary containing document text analysis
        """
        encoded_pdf = self.encode_file(pdf_path)

        request_data = {
            "inputConfig": {
                "content": encoded_pdf,
                "mimeType": "application/pdf"
            },
            "features": [
                {"type": "DOCUMENT_TEXT_DETECTION"}
            ]
        }

        if pages:
            request_data["pages"] = pages

        payload = {"requests": [request_data]}

        response = requests.post(
            f"{self.base_url}/files:annotate?key={self.api_key}",
            headers={"Content-Type": "application/json"},
            json=payload
        )

        response.raise_for_status()
        return response.json()

    def analyze_mixed_batch(self, image_paths: List[str], pdf_paths: List[str]) -> Dict[str, Any]:
        """
        Analyze both images and PDFs in a single workflow.
        Note: Due to API limitations, this makes separate calls but returns combined results.

        Args:
            image_paths: List of image file paths
            pdf_paths: List of PDF file paths

        Returns:
            Combined dictionary with results from both images and PDFs
        """
        results = {
            "images": {},
            "pdfs": {}
        }

        # Process images
        if image_paths:
            image_results = self.analyze_images(image_paths)
            for idx, img_path in enumerate(image_paths):
                results["images"][img_path] = self._format_image_result(
                    image_results["responses"][idx]
                )

        # Process PDFs
        if pdf_paths:
            for pdf_path in pdf_paths:
                pdf_result = self.analyze_pdf(pdf_path)
                results["pdfs"][pdf_path] = self._format_pdf_result(
                    pdf_result["responses"][0]
                )

        return results

    def _format_image_result(self, response: Dict[str, Any]) -> Dict[str, Any]:
        """Format image analysis response."""
        formatted = {
            "labels": [],
            "text": "",
            "objects": []
        }

        # Extract labels
        if "labelAnnotations" in response:
            formatted["labels"] = [
                {
                    "description": label["description"],
                    "score": label["score"]
                }
                for label in response["labelAnnotations"]
            ]

        # Extract text
        if "textAnnotations" in response and len(response["textAnnotations"]) > 0:
            formatted["text"] = response["textAnnotations"][0]["description"]

        # Extract objects
        if "localizedObjectAnnotations" in response:
