        self.api_key = api_key
        self.base_url = "https://vision.googleapis.com/v1"

    def encode_file(self, file_path: str) -> str:
        """Encode file to base64 string."""
        with open(file_path, 'rb') as f:
            return base64.b64encode(f.read()).decode('utf-8')

    def analyze_images(self, image_paths: List[str]) -> Dict[str, Any]:
        """
        Analyze multiple images for labels, text, and objects.

        Args:
            image_paths: List of paths to image files

        Returns:
            Dictionary containing analysis results for all images
        """
        requests_list = []

        for img_path in image_paths:
            encoded_image = self.encode_file(img_path)
            requests_list.append({
                "image": {"content": encoded_image},
                "features": [
                    {"type": "LABEL_DETECTION", "maxResults": 10},
                    {"type": "TEXT_DETECTION"},
                    {"type": "OBJECT_LOCALIZATION", "maxResults": 10}
                ]
            })

        payload = {"requests": requests_list}

        response = requests.post(
            f"{self.base_url}/images:annotate?key={self.api_key}",
            headers={"Content-Type": "application/json"},
            json=payload
        )

        response.raise_for_status()
        return response.json()

    def analyze_pdf(self, pdf_path: str, pages: List[int] = None) -> Dict[str, Any]:
        """
        Analyze PDF document for text detection.

        Args:
            pdf_path: Path to PDF file
            pages: List of page numbers to analyze (1-indexed), or None for all pages

        Returns:
            Dictionary containing document text analysis
        """
        encoded_pdf = self.encode_file(pdf_path)

        request_data = {
            "inputConfig": {
                "content": encoded_pdf,
                "mimeType": "application/pdf"
            },
            "features": [
                {"type": "DOCUMENT_TEXT_DETECTION"}
            ]
        }

        if pages:
            request_data["pages"] = pages

        payload = {"requests": [request_data]}

        response = requests.post(
            f"{self.base_url}/files:annotate?key={self.api_key}",
            headers={"Content-Type": "application/json"},
            json=payload
        )

        response.raise_for_status()
        return response.json()

    def analyze_mixed_batch(self, image_paths: List[str], pdf_paths: List[str]) -> Dict[str, Any]:
        """
        Analyze both images and PDFs in a single workflow.
        Note: Due to API limitations, this makes separate calls but returns combined results.

        Args:
