            formatted["objects"] = [
                {
                    "name": obj["name"],
                    "score": obj["score"],
                    "boundingBox": obj["boundingPoly"]
                }
                for obj in response["localizedObjectAnnotations"]
            ]

        return formatted

    def _format_pdf_result(self, response: Dict[str, Any]) -> Dict[str, Any]:
        """Format PDF analysis response."""
        formatted = {
            "text": "",
            "pages": []
        }

        if "responses" in response:
            for page_response in response["responses"]:
                if "fullTextAnnotation" in page_response:
                    formatted["text"] += page_response["fullTextAnnotation"]["text"]
                    formatted["pages"].append({
                        "text": page_response["fullTextAnnotation"]["text"]
                    })

        return formatted


def main():
    """Example usage of the Vision API client."""

