```python
import requests
import json
from typing import Dict, Any, Optional

class CoralAPIClient:
    """Client for interacting with the Coral GraphQL API."""

    def __init__(self, base_url: str, api_key: str):
        """
        Initialize the Coral API client.

        Args:
            base_url: Base URL of the Coral API (e.g., "https://api.coral.example.com")
            api_key: API authentication key
        """
        self.graphql_endpoint = f"{base_url}/graphql"
        self.headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}"
        }

    def _execute_mutation(self, query: str, variables: Dict[str, Any]) -> Dict[str, Any]:
        """
        Execute a GraphQL mutation.

        Args:
            query: GraphQL mutation query string
            variables: Variables for the mutation

        Returns:
            Response data from the API

        Raises:
            requests.HTTPError: If the request fails
        """
        payload = {
            "query": query,
            "variables": variables
        }

        response = requests.post(
            self.graphql_endpoint,
            headers=self.headers,
            data=json.dumps(payload)
        )
        response.raise_for_status()

        result = response.json()

        # Check for GraphQL errors
        if "errors" in result:
            raise Exception(f"GraphQL errors: {result['errors']}")

        return result["data"]

    def create_comment(
        self,
        story_id: str,
        body: str,
        client_mutation_id: str,
        nudge: bool = False,
        rating: Optional[int] = None,
        media: Optional[Dict[str, str]] = None
    ) -> Dict[str, Any]:
        """
        Post a new reader response (comment) on a published article.

        Args:
            story_id: ID of the story/article to comment on
            body: Text content of the comment
            client_mutation_id: Unique client-side mutation identifier
            nudge: Whether to nudge the user about comment guidelines (default: False)
            rating: Optional rating value
            media: Optional media object with keys: type, url, width, height, id

        Returns:
            Comment creation response containing the new comment edge
        """
        mutation = """
        mutation CreateComment($input: CreateCommentInput!) {
            createComment(input: $input) {
                edge {
                    node {
                        id
                        body
                        createdAt
                        author {
                            id
                            username
                        }
                        story {
                            id
                        }
                    }
                    cursor
                }
                clientMutationId
            }
        }
        """

        variables = {
            "input": {
                "storyID": story_id,
                "body": body,
                "clientMutationId": client_mutation_id,
                "nudge": nudge
            }
        }

        # Add optional parameters if provided
        if rating is not None:
            variables["input"]["rating"] = rating

        if media is not None:
            variables["input"]["media"] = media

        return self._execute_mutation(mutation, variables)

    def report_comment(
        self,
        comment_id: str,
        comment_revision_id: str,
        reason: str,
        client_mutation_id: str,
        additional_details: Optional[str] = None
    ) -> Dict[str, Any]:
        """
        Report an inappropriate reader response for moderator review.

        Args:
            comment_id: ID of the comment to report
            comment_revision_id: ID of the specific comment revision to report
            reason: Reason for reporting (one of: COMMENT_REPORTED_OFFENSIVE, 
                    COMMENT_REPORTED_ABUSIVE, COMMENT_REPORTED_SPAM, 
                    COMMENT_REPORTED_OTHER, COMMENT_REPORTED_BIO)
            client_mutation_id: Unique client-side mutation identifier
            additional_details: Optional additional context about the report

        Returns:
            Flag creation response containing the flagged comment
        """
        mutation = """
        mutation CreateCommentFlag($input: CreateCommentFlagInput!) {
            createCommentFlag(input: $input) {
                comment {
                    id
                    body
                    revisions {
                        id
                    }
                }
                clientMutationId
            }
        }
        """

        variables = {
            "input": {
                "commentID": comment_id,
                "commentRevisionID": comment_revision_id,
                "reason": reason,
                "clientMutationId": client_mutation_id
            }
        }

        # Add optional additional details if provided
        if additional_details:
            variables["input"]["additionalDetails"] = additional_details

        return self._execute_mutation(mutation, variables)


# Example usage
def main():
    # Initialize the client with placeholder credentials
    client = CoralAPIClient(
        base_url="https://api.coral.example.com",
        api_key="YOUR_API_KEY"
    )

    # Task 1: Post a new reader response on a published article
    print("=" * 60)
    print("Task 1: Posting a new reader response")
    print("=" * 60)

    try:
        comment_response = client.create_comment(
            story_id="story-abc123",
            body="Great article! I really appreciated the insights on API design.",
            client_mutation_id="mutation-1234567890"
        )

        created_comment = comment_response["createComment"]["edge"]["node"]
        print(f"✓ Comment created successfully!")
        print(f"  Comment ID: {created_comment['id']}")
        print(f"  Body: {created_comment['body']}")
        print(f"  Created at: {created_comment['createdAt']}")
        print()

    except Exception as e:
        print(f"✗ Error creating comment: {e}")
        print()

    # Task 2: Report an inappropriate reader response
    print("=" * 60)
    print("Task 2: Reporting an inappropriate reader response")
    print("=" * 60)

    try:
        flag_response = client.report_comment(
            comment_id="comment-xyz789",
            comment_revision_id="revision-456",
            reason="COMMENT_REPORTED_ABUSIVE",
            client_mutation_id="mutation-0987654321",
            additional_details="This comment contains personal attacks and violates community guidelines."
        )

        flagged_comment = flag_response["createCommentFlag"]["comment"]
        print(f"✓ Comment reported successfully!")
        print(f"  Reported Comment ID: {flagged_comment['id']}")
        print(f"  Comment will be reviewed by moderators")
        print()

    except Exception as e:
        print(f"✗ Error reporting comment: {e}")
        print()


if __name__ == "__main__":
    main()
```

### Notes

**Authentication Requirements:**
- The API requires authentication via Bearer token in the Authorization header
- User must be logged in to create comments and flag content
- Use placeholder value "YOUR_API_KEY" for this exercise

**Valid Report Reasons:**
The `createCommentFlag` mutation accepts the following report reasons:
- `COMMENT_REPORTED_OFFENSIVE`: Content is offensive
- `COMMENT_REPORTED_ABUSIVE`: Content is abusive or harassing
- `COMMENT_REPORTED_SPAM`: Content is spam
- `COMMENT_REPORTED_OTHER`: Other reason not listed
- `COMMENT_REPORTED_BIO`: Issue with user bio

**Required Fields:**
- `createComment` requires: `storyID`, `body`, and `clientMutationId`
- `createCommentFlag` requires: `commentID`, `commentRevisionID`, `reason`, and `clientMutationId`

**Optional Features:**
- Comments can include media attachments (images/videos) via the `media` parameter
- Comments can include ratings via the `rating` parameter
- The `nudge` parameter can be used to show comment guidelines to users
- Additional details can be provided when flagging to give moderators more context

**API Behavior:**
- The `createCommentFlag` mutation sends the report to moderators for review
- Multiple users can flag the same comment
- Flagged comments may enter a moderation queue depending on configuration
- The `clientMutationId` should be unique per mutation to prevent duplicate operations

**Rate Limits:**
- Rate limit information not specified in documentation
- Implement exponential backoff for production use

