### Code Example

```python
import base64
import json
import requests
from typing import List, Dict, Any


class GoogleVisionAPIClient:
    """Client for Google Cloud Vision API v1"""

    def __init__(self, api_key: str):
        """
        Initialize the Vision API client.

        Args:
            api_key: Your Google Cloud API key
        """
        self.api_key = api_key
        self.base_url = "https://vision.googleapis.com/v1"

    def analyze_images(self, image_paths: List[str]) -> Dict[str, Any]:
        """
        Analyze multiple images for labels, text, and objects.

        Args:
            image_paths: List of paths to image files

        Returns:
            API response with annotations for all images
        """
        # Prepare request body
        requests_list = []

        for image_path in image_paths:
            # Read and encode image
            with open(image_path, 'rb') as image_file:
                image_content = base64.b64encode(image_file.read()).decode('utf-8')

            # Build request for this image
            image_request = {
                "image": {
                    "content": image_content
                },
                "features": [
                    {
                        "type": "LABEL_DETECTION",
                        "maxResults": 10
                    },
                    {
                        "type": "TEXT_DETECTION"
                    },
                    {
                        "type": "OBJECT_LOCALIZATION",
                        "maxResults": 10
                    }
                ]
            }
            requests_list.append(image_request)

        # Make API call
        endpoint = f"{self.base_url}/images:annotate"
        params = {"key": self.api_key}
        payload = {"requests": requests_list}

        response = requests.post(endpoint, params=params, json=payload)
        response.raise_for_status()

        return response.json()

    def analyze_pdfs(self, pdf_paths: List[str], pages_per_pdf: List[int] = None) -> Dict[str, Any]:
        """
        Analyze PDF documents for labels, text, and objects.

        Args:
            pdf_paths: List of paths to PDF files
            pages_per_pdf: Optional list specifying which pages to analyze (max 5 per PDF)

        Returns:
            API response with annotations for all PDFs
        """
        # Prepare request body
        requests_list = []

        for i, pdf_path in enumerate(pdf_paths):
            # Read and encode PDF
            with open(pdf_path, 'rb') as pdf_file:
                pdf_content = base64.b64encode(pdf_file.read()).decode('utf-8')

            # Determine which pages to analyze (default: first 5)
            pages = pages_per_pdf[i] if pages_per_pdf and i < len(pages_per_pdf) else [1, 2, 3, 4, 5]

            # Build request for this PDF
            pdf_request = {
                "inputConfig": {
                    "content": pdf_content,
                    "mimeType": "application/pdf"
                },
                "features": [
                    {
                        "type": "LABEL_DETECTION",
                        "maxResults": 10
                    },
                    {
                        "type": "DOCUMENT_TEXT_DETECTION"
                    },
                    {
                        "type": "OBJECT_LOCALIZATION",
                        "maxResults": 10
                    }
                ],
                "pages": pages
            }
            requests_list.append(pdf_request)

        # Make API call
        endpoint = f"{self.base_url}/files:annotate"
        params = {"key": self.api_key}
        payload = {"requests": requests_list}

        response = requests.post(endpoint, params=params, json=payload)
        response.raise_for_status()

        return response.json()

    def print_image_results(self, response: Dict[str, Any]):
        """Print formatted results from image analysis."""
        for idx, result in enumerate(response.get('responses', [])):
            print(f"\n=== Image {idx + 1} Results ===")

            # Print labels
            if 'labelAnnotations' in result:
                print("\nLabels detected:")
                for label in result['labelAnnotations']:
                    print(f"  - {label['description']} (confidence: {label['score']:.2f})")

            # Print text
            if 'textAnnotations' in result and result['textAnnotations']:
                print("\nText detected:")
                print(f"  {result['textAnnotations'][0]['description'][:100]}...")

            # Print objects
            if 'localizedObjectAnnotations' in result:
                print("\nObjects detected:")
                for obj in result['localizedObjectAnnotations']:
                    print(f"  - {obj['name']} (confidence: {obj['score']:.2f})")

            # Print errors if any
            if 'error' in result:
                print(f"\nError: {result['error']}")

    def print_pdf_results(self, response: Dict[str, Any]):
        """Print formatted results from PDF analysis."""
        for file_idx, file_result in enumerate(response.get('responses', [])):
            print(f"\n=== PDF {file_idx + 1} Results ===")
            print(f"Total pages: {file_result.get('totalPages', 'N/A')}")

            for page_idx, page_result in enumerate(file_result.get('responses', [])):
                print(f"\n--- Page {page_idx + 1} ---")

