### Code Example

```python
import requests
import json
from typing import Dict, Any, List
from concurrent.futures import ThreadPoolExecutor, as_completed

class DualClusterSearchClient:
    """
    Client for executing search queries across both current and legacy
    Elasticsearch clusters simultaneously via GraphQL API.
    """

    def __init__(self, graphql_endpoint: str, current_host: str, legacy_host: str):
        """
        Initialize the dual cluster search client.

        Args:
            graphql_endpoint: The GraphQL API endpoint (e.g., "http://api.example.com/graphql")
            current_host: Current-gen cluster URL (Elastic 7.7)
            legacy_host: Legacy cluster URL (Elastic 5.6)
        """
        self.graphql_endpoint = graphql_endpoint
        self.current_host = current_host
        self.legacy_host = legacy_host
        self.session = requests.Session()
        self.session.headers.update({
            'Content-Type': 'application/json',
            'Authorization': 'Bearer YOUR_API_KEY'  # Placeholder for authentication
        })

    def build_search_query(self, version: str, host: str, search_body: Dict[str, Any], 
                          index: List[str], size: int = 10) -> str:
        """
        Build a GraphQL query for the specified Elasticsearch version.

        Args:
            version: Elasticsearch version field name (elastic77 or elastic56)
            host: Cluster host URL
            search_body: Elasticsearch query DSL
            index: List of indices to search
            size: Number of results to return

        Returns:
            GraphQL query string
        """
        # Escape and format the search body for GraphQL
        search_body_json = json.dumps(search_body)
        index_json = json.dumps(index)

        query = f"""
        query {{
          {version}(host: "{host}") {{
            search(
              body: {search_body_json}
              index: {index_json}
              size: {size}
            )
          }}
        }}
        """
        return query

    def execute_search(self, version: str, host: str, search_body: Dict[str, Any],
                      index: List[str], size: int = 10) -> Dict[str, Any]:
        """
        Execute a search query against a specific cluster version.

        Args:
            version: Elasticsearch version (elastic77 or elastic56)
            host: Cluster host URL
            search_body: Elasticsearch query DSL
            index: List of indices to search
            size: Number of results

        Returns:
            Search results from the cluster
        """
        query = self.build_search_query(version, host, search_body, index, size)

        payload = {
            'query': query
        }

        try:
            response = self.session.post(
                self.graphql_endpoint,
                json=payload,
                timeout=30
            )
            response.raise_for_status()

            result = response.json()

            # Extract the search results from GraphQL response
            if 'data' in result and version in result['data']:
                return {
                    'version': version,
                    'host': host,
                    'success': True,
                    'results': result['data'][version]['search']
                }
            else:
                return {
                    'version': version,
                    'host': host,
                    'success': False,
                    'error': result.get('errors', 'Unknown error')
                }

        except requests.exceptions.RequestException as e:
            return {
                'version': version,
                'host': host,
                'success': False,
                'error': str(e)
            }

    def search_both_clusters(self, search_body: Dict[str, Any], 
                            index: List[str], size: int = 10) -> Dict[str, Any]:
        """
        Execute the same search query across both clusters simultaneously.

        Args:
            search_body: Elasticsearch query DSL
            index: List of indices to search
            size: Number of results per cluster

        Returns:
            Combined results from both clusters
        """
        # Execute searches in parallel using ThreadPoolExecutor
        with ThreadPoolExecutor(max_workers=2) as executor:
            # Submit both searches
            future_current = executor.submit(
                self.execute_search,
                'elastic77',
                self.current_host,
                search_body,
                index,
                size
            )

            future_legacy = executor.submit(
                self.execute_search,
                'elastic56',
                self.legacy_host,
                search_body,
                index,
                size
            )

            # Collect results as they complete
            results = {
                'current_gen': None,
                'previous_gen': None
            }

            for future in as_completed([future_current, future_legacy]):
                result = future.result()
                if result['version'] == 'elastic77':
                    results['current_gen'] = result
                else:
                    results['previous_gen'] = result

        return results

    def compare_results(self, dual_results: Dict[str, Any]) -> Dict[str, Any]:
        """
        Compare and analyze results from both cluster versions.

        Args:
            dual_results: Results from search_both_clusters()

        Returns:
            Comparison analysis
        """
        current = dual_results['current_gen']
        previous = dual_results['previous_gen']

        comparison = {
            'both_successful': current['success'] and previous['success'],
            'current_gen': {
                'version': 'Elasticsearch 7.7',
                'status': 'success' if current['success'] else 'failed',
                'host': current['host']
            },
            'previous_gen': {
                'version': 'Elasticsearch 5.6',
                'status': 'success' if previous['success'] else 'failed',
                'host': previous['host']
            }
        }

        # Add performance metrics if both succeeded
        if comparison['both_successful']:
            current_results = current['results']
            previous_results = previous['results']

            comparison['performance'] = {
                'current_gen_took_ms': current_results.get('took'),
                'previous_gen_took_ms': previous_results.get('took')
            }

            comparison['hit_counts'] = {
                'current_gen': current_results.get('hits', {}).get('total'),
                'previous_gen': previous_results.get('hits', {}).get('total')
            }

        return comparison


# Example usage
def main():
    # Initialize the dual cluster client
    client = DualClusterSearchClient(
        graphql_endpoint="http://api.example.com/graphql",
        current_host="http://user:pass@current-cluster.example.com:9200",
        legacy_host="http://user:pass@legacy-cluster.example.com:9200"
    )

    # Define a search query using Elasticsearch Query DSL
    search_query = {
        "query": {
            "bool": {
                "must": [
                    {
                        "match": {
                            "title": "search term"
                        }
                    }
                ],
                "filter": [
                    {
                        "range": {
                            "price": {
                                "gte": 10,
                                "lte": 100
                            }
                        }
                    }
                ]
            }
        },
        "sort": [
            {"_score": "desc"},
            {"created_at": "desc"}
        ]
    }

    # Execute search across both clusters simultaneously
    print("Executing search across both cluster versions...")
    results = client.search_both_clusters(
        search_body=search_query,
        index=["products"],
        size=10
    )

    # Display results
    print("\n=== DUAL CLUSTER SEARCH RESULTS ===\n")
    print(f"Current Generation (Elastic 7.7): {results['current_gen']['success']}")
    if results['current_gen']['success']:
        print(f"  Hits: {results['current_gen']['results'].get('hits', {}).get('total')}")
        print(f"  Time: {results['current_gen']['results'].get('took')}ms")

    print(f"\nPrevious Generation (Elastic 5.6): {results['previous_gen']['success']}")
    if results['previous_gen']['success']:
        print(f"  Hits: {results['previous_gen']['results'].get('hits', {}).get('total')}")
        print(f"  Time: {results['previous_gen']['results'].get('took')}ms")

    # Compare results
    comparison = client.compare_results(results)
    print("\n=== COMPARISON ===")
    print(json.dumps(comparison, indent=2))


if __name__ == "__main__":
    main()
```

### Notes

1. **Authentication**: The code uses placeholder `YOUR_API_KEY` for authentication. Replace with actual API credentials based on the authentication mechanism of the GraphQL endpoint.

2. **Host Format**: Both `elastic77` and `elastic56` query fields accept a `host` parameter in the format `http://user:pass@hostname:port`. The default shown in documentation is `http://user:pass@example.com:9200`.

3. **Parallel Execution**: The implementation uses `ThreadPoolExecutor` to execute searches against both clusters simultaneously, maximizing performance when comparing results across platform versions.

4. **Query DSL Compatibility**: While the same query structure can be sent to both clusters, be aware that Elasticsearch 5.6 and 7.7 may have different features and query capabilities. Some query types available in 7.7 may not be supported in 5.6.

