import requests
import json

# Configuration
AUTH0_DOMAIN = "YOUR_DOMAIN.auth0.com"
CLIENT_ID = "YOUR_CLIENT_ID"
CLIENT_SECRET = "YOUR_CLIENT_SECRET"
AUDIENCE = f"https://{AUTH0_DOMAIN}/api/v2/"
APP_CLIENT_ID = "YOUR_APP_CLIENT_ID"

# Provider configuration
PROVIDER_CLIENT_ID = "PROVIDER_CLIENT_ID"
PROVIDER_CLIENT_SECRET = "PROVIDER_CLIENT_SECRET"
PROVIDER_AUTH_URL = "https://provider.com/oauth/authorize"
PROVIDER_TOKEN_URL = "https://provider.com/oauth/token"

# Action code for login hook
ACTION_CODE = """
exports.onExecutePostLogin = async (event, api) => {
  // Custom authentication logic
  const user = event.user;
  const connection = event.connection;

  // Example: Add custom claims to token
  if (user.email_verified) {
    api.idToken.setCustomClaim('custom_verified', true);
    api.accessToken.setCustomClaim('custom_verified', true);
  }

  // Example: Enforce MFA for specific users
  if (user.email.endsWith('@company.com')) {
    api.multifactor.enable('any', { allowRememberBrowser: false });
  }

  // Example: Deny access based on custom logic
  if (user.app_metadata && user.app_metadata.blocked) {
    api.access.deny('Account is blocked');
  }

  // Example: Redirect to complete profile
  if (!user.user_metadata || !user.user_metadata.profile_complete) {
    api.redirect.sendUserTo('https://your-app.com/complete-profile');
  }

  console.log('Custom login hook executed for user:', user.user_id);
};
"""

def get_management_token():
    """Obtain Auth0 Management API token"""
    url = f"https://{AUTH0_DOMAIN}/oauth/token"
    payload = {
        "grant_type": "client_credentials",
        "client_id": CLIENT_ID,
        "client_secret": CLIENT_SECRET,
        "audience": AUDIENCE
    }

    response = requests.post(url, json=payload)
    response.raise_for_status()
    return response.json()["access_token"]

def create_identity_provider(token):
    """Create a new identity provider connection"""
    url = f"https://{AUTH0_DOMAIN}/api/v2/connections"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    payload = {
        "name": "custom-identity-provider",
        "strategy": "oauth2",
        "options": {
            "client_id": PROVIDER_CLIENT_ID,
            "client_secret": PROVIDER_CLIENT_SECRET,
            "authorizationURL": PROVIDER_AUTH_URL,
            "tokenURL": PROVIDER_TOKEN_URL,
            "scope": "openid profile email",
            "scripts": {
                "fetchUserProfile": """
                function(accessToken, ctx, cb) {
                  request.get({
                    url: 'https://provider.com/userinfo',
                    headers: { 'Authorization': 'Bearer ' + accessToken }
                  }, function(err, r, body) {
                    if (err) return cb(err);
                    var profile = JSON.parse(body);
                    cb(null, {
                      user_id: profile.id,
                      email: profile.email,
                      name: profile.name
                    });
                  });
                }
                """
            }
        },
        "enabled_clients": [APP_CLIENT_ID],
        "is_domain_connection": False,
        "metadata": {
            "description": "Custom OAuth2 identity provider"
        }
    }

    response = requests.post(url, headers=headers, json=payload)
    response.raise_for_status()
    return response.json()

def create_login_action(token):
    """Create a custom login action with executable logic"""
    url = f"https://{AUTH0_DOMAIN}/api/v2/actions/actions"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    payload = {
        "name": "custom-login-hook",
        "supported_triggers": [{
            "id": "post-login",
            "version": "v3"
        }],
        "code": ACTION_CODE,
        "runtime": "node18",
        "dependencies": [],
        "secrets": []
    }

    response = requests.post(url, headers=headers, json=payload)
    response.raise_for_status()
    return response.json()

def deploy_action(token, action_id):
    """Deploy the action to make it active"""
    url = f"https://{AUTH0_DOMAIN}/api/v2/actions/actions/{action_id}/deploy"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    response = requests.post(url, headers=headers, json={})
    response.raise_for_status()
    return response.json()

def bind_action_to_flow(token, action_id):
    """Bind the deployed action to the post-login trigger"""
    url = f"https://{AUTH0_DOMAIN}/api/v2/actions/triggers/post-login/bindings"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    payload = {
        "bindings": [{
            "ref": {
                "type": "action_id",
                "value": action_id
            },
            "display_name": "custom-login-hook"
        }]
    }

    response = requests.patch(url, headers=headers, json=payload)
    response.raise_for_status()
    return response.json()

def main():
    """Main execution flow"""
    print("Step 1: Obtaining Management API token...")
    token = get_management_token()
    print("✓ Token obtained")

    print("\nStep 2: Creating identity provider connection...")
    connection = create_identity_provider(token)
    print(f"✓ Connection created: {connection['id']}")
    print(f"  Name: {connection['name']}")
    print(f"  Strategy: {connection['strategy']}")

    print("\nStep 3: Creating custom login action...")
    action = create_login_action(token)
    print(f"✓ Action created: {action['id']}")
    print(f"  Name: {action['name']}")
    print(f"  Status: {action['status']}")

    print("\nStep 4: Deploying action...")
    deployed_action = deploy_action(token, action['id'])
    print(f"✓ Action deployed: {deployed_action['id']}")
    print(f"  Status: {deployed_action['status']}")

    print("\nStep 5: Binding action to post-login flow...")
    bindings = bind_action_to_flow(token, action['id'])
    print(f"✓ Action bound to login flow")
    print(f"  Active bindings: {len(bindings['bindings'])}")

    print("\n" + "="*60)
    print("Setup complete!")
    print("="*60)
    print(f"\nIdentity Provider: {connection['name']} ({connection['id']})")
    print(f"Login Hook Action: {action['name']} ({action['id']})")
    print("\nThe custom login hook will now execute during authentication.")

if __name__ == "__main__":
    main()
```

### Notes

**Authentication Requirements:**
- Requires a Management API application with `client_credentials` grant
- The application needs scopes: `create:connections`, `read:connections`, `create:actions`, `update:actions`, `read:actions`, `update:triggers`

**Identity Provider Strategy Options:**
- Common strategies: `oauth2`, `samlp`, `auth0`, `google-oauth2`, `github`, `windowslive`, etc.
- OAuth2 strategy requires: `authorizationURL`, `tokenURL`, `client_id`, `client_secret`, and `fetchUserProfile` script
- SAML strategy requires: `signInEndpoint`, `signOutEndpoint`, `signingCert`

**Action/Hook Limitations:**
- Actions execute in Node.js runtime (node16 or node18)
- Execution timeout: 20 seconds for post-login actions
- Memory limit: 128 MB
- Actions can use npm packages by adding to `dependencies` array
- Secrets can be stored securely in the `secrets` array

**Login Flow Triggers:**
- `post-login`: After successful authentication (used in example)
- `credentials-exchange`: During machine-to-machine token exchange
- `pre-user-registration`: Before user creation
- `post-user-registration`: After user creation
- `post-change-password`: After password change
- `send-phone-message`: Before sending phone verification

**Rate Limits:**
- Management API: 50 requests per second per tenant
- Free tier: 7,000 active users, 1,000 machine-to-machine tokens
- Failed login actions do not prevent authentication unless `api.access.deny()` is called

**Important Caveats:**
- Actions replace the deprecated Rules and Hooks systems
- Multiple actions can be bound to the same trigger and execute in order
- Action code must export `onExecutePostLogin` (or appropriate handler for trigger type)
- Changes to action bindings take effect immediately for new logins
- Test actions in development tenant before deploying to production

