    gateway = BraintreePaymentGateway(
        endpoint="https://payments.sandbox.braintree-api.com",
        public_key="YOUR_PUBLIC_KEY",
        private_key="YOUR_PRIVATE_KEY"
    )

    # Step 1: Create a new buyer profile
    print("Creating customer profile...")
