        first_name="Jane",
        last_name="Smith",
        email="jane.smith@example.com",
        phone_number="+14155559876",
        company="Acme Corporation"
    )
    print(f"Customer created: {customer['id']}")

    # Step 2: Vault a payment method for the customer
    # Note: payment_method_id would typically come from client-side tokenization
    print("\nVaulting payment method...")
    payment_method = gateway.vault_payment_method(
        payment_method_id="tokencc_bf_sample_token_id",  # Placeholder token
        customer_id=customer["id"]
    )
    print(f"Payment method vaulted: {payment_method['id']}")

    # Step 3: Process a payment with shipping and fraud risk data
    print("\nProcessing payment...")

    shipping_address = {
        "firstName": "Jane",
        "lastName": "Smith",
        "streetAddress": "456 Market Street",
        "locality": "San Francisco",
        "region": "CA",
        "postalCode": "94102",
        "countryCodeAlpha2": "US"
    }

    # Fraud detection device data (would be collected client-side)
    device_data = json.dumps({
        "device_session_id": "bf6ecfd3b976a3a12451742c29932aeb",
        "fraud_merchant_id": "600000"
    })

    transaction = gateway.charge_payment_method(
        payment_method_id=payment_method["id"],
        amount=99.99,
        order_id=f"ORDER-{uuid.uuid4()}",
        shipping_address=shipping_address,
        device_data=device_data,
        channel="WEB"
    )

    print(f"Transaction completed: {transaction['id']}")
    print(f"Status: {transaction['status']}")
    print(f"Amount: {transaction['amount']['value']} {transaction['amount']['currencyIsoCode']}")


if __name__ == "__main__":
    main()
