import requests
import json
import uuid
from typing import Dict, Any

class BraintreePaymentGateway:
    """
    Braintree GraphQL API integration for buyer registration and payment processing
    """

    def __init__(self, endpoint: str, public_key: str, private_key: str):
        """
        Initialize Braintree API client

        Args:
            endpoint: Braintree GraphQL endpoint URL
            public_key: Your Braintree public API key
            private_key: Your Braintree private API key
        """
        self.endpoint = f"{endpoint}/graphql"
        self.auth = (public_key, private_key)
        self.headers = {
            "Content-Type": "application/json",
            "Accept": "application/json",
            "Braintree-Version": "2019-12-17"
        }

    def _execute_graphql(self, query: str, variables: Dict[str, Any]) -> Dict[str, Any]:
        """
        Execute a GraphQL query/mutation

        Args:
            query: GraphQL query or mutation string
            variables: Variables for the GraphQL operation

        Returns:
            Response data from the API
        """
        payload = {
            "query": query,
            "variables": variables
        }

        response = requests.post(
            self.endpoint,
            auth=self.auth,
            headers=self.headers,
            json=payload
        )
        response.raise_for_status()
        return response.json()

    def create_customer(self, first_name: str, last_name: str, email: str, 
                       phone_number: str = None, company: str = None) -> Dict[str, Any]:
        """
        Create a new buyer/customer profile

        Args:
            first_name: Customer's first name
            last_name: Customer's last name
            email: Customer's email address
            phone_number: Customer's phone number (optional)
            company: Customer's company name (optional)

        Returns:
            Customer data including ID
        """
        query = """
        mutation CreateCustomer($input: CreateCustomerInput!) {
          createCustomer(input: $input) {
            clientMutationId
            customer {
                id
                legacyId
                firstName
                lastName
                company
                createdAt
            }
          }
        }
        """

        customer_data = {
            "firstName": first_name,
            "lastName": last_name,
            "email": email
        }

        if phone_number:
            customer_data["phoneNumber"] = phone_number
        if company:
            customer_data["company"] = company

        variables = {
            "input": {
                "clientMutationId": str(uuid.uuid4()),
                "customer": customer_data
            }
        }

        result = self._execute_graphql(query, variables)
        return result["data"]["createCustomer"]["customer"]

    def vault_payment_method(self, payment_method_id: str, customer_id: str) -> Dict[str, Any]:
        """
        Vault (save) a payment method for a customer

        Args:
            payment_method_id: Tokenized payment method ID from client-side
            customer_id: Customer ID to associate payment method with

        Returns:
            Payment method data
        """
        query = """
        mutation VaultPaymentMethod($input: VaultPaymentMethodInput!) {
          vaultPaymentMethod(input: $input) {
            clientMutationId
            paymentMethod {
                id
                legacyId
                usage
                createdAt
                details {
                    __typename
                    ... on CreditCardDetails {
                        brandCode
                        last4
                    }
                    ... on PayPalAccountDetails {
                        billingAgreementId
                        email
                        payerId
                        firstName
                        lastName
                    }
                }
                customer {
                    id
                }
            }
          }
        }
        """

        variables = {
            "input": {
                "clientMutationId": str(uuid.uuid4()),
                "paymentMethodId": payment_method_id,
                "customerId": customer_id
            }
        }

        result = self._execute_graphql(query, variables)
        return result["data"]["vaultPaymentMethod"]["paymentMethod"]

    def charge_payment_method(self, payment_method_id: str, amount: float,
                             order_id: str, shipping_address: Dict[str, str],
                             device_data: str, channel: str = "WEB") -> Dict[str, Any]:
        """
        Process a payment using a saved payment method with shipping and fraud risk data

        Args:
            payment_method_id: ID of the vaulted payment method
            amount: Transaction amount
            order_id: Merchant's order identifier
            shipping_address: Dictionary with shipping address fields:
                - firstName, lastName, streetAddress, locality, region,
                  postalCode, countryCodeAlpha2
            device_data: Fraud detection device data (JSON string)
            channel: Transaction channel (default: "WEB")

        Returns:
            Transaction data
        """
        query = """
        mutation ChargePaymentMethod($input: ChargePaymentMethodInput!) {
          chargePaymentMethod(input: $input) {
            clientMutationId
            transaction {
                id
                legacyId
                createdAt
                paymentMethod {
                    id
                    legacyId
                }
                amount {
                    value
                    currencyIsoCode
                }
                merchantAccountId
                orderId
                purchaseOrderNumber
                status
                statusHistory {
                    status
                    timestamp
                    amount {
                        value
                        currencyIsoCode
                    }
                }
                source
            }
          }
        }
        """

        variables = {
            "input": {
                "clientMutationId": str(uuid.uuid4()),
                "paymentMethodId": payment_method_id,
                "transaction": {
                    "amount": amount,
                    "orderId": order_id,
                    "shipping": {
                        "shippingAddress": shipping_address
                    },
                    "riskData": {
                        "deviceData": device_data
                    },
                    "channel": channel
                }
            }
        }

        result = self._execute_graphql(query, variables)
        return result["data"]["chargePaymentMethod"]["transaction"]


