        customer_id=customer["id"]
    )
    print(f"Payment method vaulted: {payment_method['id']}")

    # Step 3: Process a payment with shipping and fraud risk data
    print("\nProcessing payment...")

    shipping_address = {
        "firstName": "Jane",
        "lastName": "Smith",
        "streetAddress": "456 Market Street",
        "locality": "San Francisco",
        "region": "CA",
        "postalCode": "94102",
        "countryCodeAlpha2": "US"
    }

    # Fraud detection device data (would be collected client-side)
