import requests
import json

# API Configuration
API_ENDPOINT = "https://metaphysics-production.artsy.net/v2"
API_KEY = "YOUR_API_KEY"

headers = {
    "Content-Type": "application/json",
    "X-ACCESS-TOKEN": API_KEY
}

def browse_artworks(category_slug, filter_slug, price_range=None, availability=None, artist_id=None, limit=10):
    """
    Browse available pieces in the gallery with filters.

    Args:
        category_slug: Category identifier (e.g., "contemporary-art")
        filter_slug: Filter identifier (e.g., "artworks-for-sale")
        price_range: Price range filter (e.g., "1000-5000" for $10-$50)
        availability: Availability filter (e.g., "FOR_SALE")
        artist_id: Artist ID to filter by specific creator
        limit: Number of results to return

    Returns:
        List of artwork objects
    """
    query = """
    query BrowseArtworks(
        $categorySlug: String!,
        $filterSlug: String!,
        $priceRange: String,
        $availability: String,
        $artistID: String,
        $forSale: Boolean,
        $first: Int
    ) {
        discoveryCategoryArtworksConnection(
            categorySlug: $categorySlug,
            filterSlug: $filterSlug,
            priceRange: $priceRange,
            availability: $availability,
            artistID: $artistID,
            forSale: $forSale,
            first: $first
        ) {
            edges {
                node {
                    id
                    internalID
                    title
                    artistNames
                    price
                    priceCurrency
                    priceDisplay
                    availability
                    isAcquireable
                    isBuyNowable
                    isPurchasable
                    href
                    medium
                    date
                }
            }
            pageCursors {
                first {
                    cursor
                }
                last {
                    cursor
                }
            }
        }
    }
    """

    variables = {
        "categorySlug": category_slug,
        "filterSlug": filter_slug,
        "first": limit
    }

    if price_range:
        variables["priceRange"] = price_range
    if availability:
        variables["availability"] = availability
    if artist_id:
        variables["artistID"] = artist_id

    # Set forSale to true if availability is FOR_SALE
    if availability == "FOR_SALE":
        variables["forSale"] = True

    payload = {
        "query": query,
        "variables": variables
    }

    response = requests.post(API_ENDPOINT, json=payload, headers=headers)
    response.raise_for_status()

    data = response.json()
    artworks = data.get("data", {}).get("discoveryCategoryArtworksConnection", {}).get("edges", [])

    return [edge["node"] for edge in artworks]


def create_order(artwork_id, edition_set_id=None, quantity=1):
    """
    Create a purchase order for a chosen artwork.

    Args:
        artwork_id: The ID of the artwork to purchase
        edition_set_id: Optional edition set ID if artwork has multiple editions
        quantity: Number of pieces to purchase (default: 1)

    Returns:
        Order object with order ID
    """
    mutation = """
    mutation CreateOrder(
        $artworkId: String!,
        $editionSetId: String,
        $quantity: Int
    ) {
        commerceCreateOrderWithArtwork(
            input: {
                artworkId: $artworkId,
                editionSetId: $editionSetId,
                quantity: $quantity
            }
        ) {
            orderOrError {
                ... on CommerceOrderWithMutationSuccess {
                    order {
                        id
                        internalID
                        state
                        itemsTotal(precision: 2)
                        totalListPrice(precision: 2)
                    }
                }
                ... on CommerceOrderWithMutationFailure {
                    error {
                        type
                        code
                        data
                    }
                }
            }
        }
    }
    """

    variables = {
        "artworkId": artwork_id,
        "quantity": quantity
    }

    if edition_set_id:
        variables["editionSetId"] = edition_set_id

    payload = {
        "query": mutation,
        "variables": variables
    }

    response = requests.post(API_ENDPOINT, json=payload, headers=headers)
    response.raise_for_status()

    data = response.json()
    order_or_error = data.get("data", {}).get("commerceCreateOrderWithArtwork", {}).get("orderOrError", {})

    if "order" in order_or_error:
        return order_or_error["order"]
    else:
        raise Exception(f"Order creation failed: {order_or_error.get('error', {})}")


def submit_order(order_id):
    """
    Submit the order to complete the purchase.

    Args:
        order_id: The ID of the order to submit

    Returns:
        Submitted order object
    """
    mutation = """
    mutation SubmitOrder($orderId: ID!) {
        commerceSubmitOrder(input: { id: $orderId }) {
            orderOrError {
                ... on CommerceOrderWithMutationSuccess {
                    order {
                        id
                        internalID
                        state
                        stateReason
                        itemsTotal(precision: 2)
                        totalListPrice(precision: 2)
                    }
                }
                ... on CommerceOrderWithMutationFailure {
                    error {
                        type
                        code
                        data
                    }
                }
            }
        }
    }
    """

    variables = {
        "orderId": order_id
    }

    payload = {
        "query": mutation,
        "variables": variables
    }

    response = requests.post(API_ENDPOINT, json=payload, headers=headers)
    response.raise_for_status()

    data = response.json()
    order_or_error = data.get("data", {}).get("commerceSubmitOrder", {}).get("orderOrError", {})

    if "order" in order_or_error:
        return order_or_error["order"]
    else:
        raise Exception(f"Order submission failed: {order_or_error.get('error', {})}")


def main():
