    """
    print("=" * 60)
    print("Gallery Artwork Browser and Purchase System")
    print("=" * 60)

    # Step 1: Browse artworks with filters
    print("\n1. Browsing available artworks...")
    print("   Filters:")
    print("   - Price Range: $10 - $50 (1000-5000 cents)")
    print("   - Availability: FOR_SALE")
    print("   - Category: contemporary-art")

    try:
        artworks = browse_artworks(
            category_slug="contemporary-art",
            filter_slug="artworks-for-sale",
            price_range="1000-5000",  # $10 to $50
            availability="FOR_SALE",
            limit=10
        )

        print(f"\n   Found {len(artworks)} artworks\n")

        # Display available artworks
        for idx, artwork in enumerate(artworks, 1):
            print(f"   [{idx}] {artwork['title']}")
            print(f"       Artist: {artwork['artistNames']}")
            print(f"       Price: {artwork.get('priceDisplay', 'N/A')}")
            print(f"       Availability: {artwork['availability']}")
            print(f"       Purchasable: {artwork.get('isPurchasable', False)}")
            print(f"       ID: {artwork['internalID']}")
            print()

        # Step 2: Select an artwork (choosing the first one for this example)
        if not artworks:
            print("No artworks found matching the criteria.")
            return

        chosen_artwork = artworks[0]
        print(f"\n2. Selected artwork: '{chosen_artwork['title']}' by {chosen_artwork['artistNames']}")

        # Step 3: Create an order
        print("\n3. Creating purchase order...")
        order = create_order(artwork_id=chosen_artwork["internalID"])

        print(f"   Order created successfully!")
        print(f"   Order ID: {order['id']}")
        print(f"   Order State: {order['state']}")
        print(f"   Total Price: {order.get('totalListPrice', 'N/A')}")

        # Step 4: Submit the order
        print("\n4. Submitting order...")
        submitted_order = submit_order(order_id=order["id"])

        print(f"   Order submitted successfully!")
        print(f"   Final State: {submitted_order['state']}")
        print(f"   Order ID: {submitted_order['id']}")

        print("\n" + "=" * 60)
        print("Purchase completed successfully!")
        print("=" * 60)

    except requests.exceptions.RequestException as e:
        print(f"\nAPI Request Error: {e}")
    except Exception as e:
        print(f"\nError: {e}")


if __name__ == "__main__":
    main()
