    query = """
    query GetAllFilms($first: Int, $after: String) {
      allFilms(first: $first, after: $after) {
        pageInfo {
          hasNextPage
          endCursor
        }
        totalCount
        films {
          id
          title
          episodeID
          director
          producers
          releaseDate
          openingCrawl
        }
      }
    }
    """

    all_films = []
    after_cursor = None
    has_next_page = True

    while has_next_page:
        variables = {
            "first": page_size,
            "after": after_cursor
        }

        response = requests.post(
            GRAPHQL_ENDPOINT,
            json={"query": query, "variables": variables},
            headers={
                "Content-Type": "application/json",
                # "Authorization": f"Bearer {API_KEY}"  # Uncomment if auth required
