import requests
import json

class WorkItemTracker:
    """Client for interacting with Linear API to manage work items."""

    def __init__(self, api_key):
        self.api_key = api_key
        self.base_url = "https://api.linear.app/graphql"
        self.headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json"
        }

    def get_issue(self, issue_id):
        """
        Retrieve details of a specific work item.

        Args:
            issue_id: The unique identifier of the issue

        Returns:
            dict: Issue details including id, title, state, assignee, priority
        """
        query = """
            query GetIssue($id: String!) {
                issue(id: $id) {
                    id
                    title
                    description
                    state {
                        id
                        name
                    }
                    assignee {
                        id
                        name
                        email
                    }
                    priority
                    createdAt
                    updatedAt
                }
            }
        """

        payload = {
            "query": query,
            "variables": {"id": issue_id}
        }

        response = requests.post(self.base_url, headers=self.headers, json=payload)
        response.raise_for_status()

        data = response.json()
        if "errors" in data:
            raise Exception(f"GraphQL errors: {data['errors']}")

        return data["data"]["issue"]

    def update_issue(self, issue_id, state_id=None, assignee_id=None, priority=None):
        """
        Update properties of a work item.

        Args:
            issue_id: The unique identifier of the issue
            state_id: New state/status ID (optional)
            assignee_id: New assignee user ID (optional)
            priority: New priority level 0-4 (optional)
                     0=No priority, 1=Urgent, 2=High, 3=Medium, 4=Low

        Returns:
            dict: Updated issue details
        """
        mutation = """
            mutation UpdateIssue($id: String!, $input: IssueUpdateInput!) {
                issueUpdate(id: $id, input: $input) {
                    success
                    issue {
                        id
                        title
                        state {
                            id
                            name
                        }
                        assignee {
                            id
                            name
                            email
                        }
                        priority
                        updatedAt
                    }
                }
            }
        """

        # Build input object with only provided fields
        update_input = {}
        if state_id is not None:
            update_input["stateId"] = state_id
        if assignee_id is not None:
            update_input["assigneeId"] = assignee_id
        if priority is not None:
            update_input["priority"] = priority

        payload = {
            "query": mutation,
            "variables": {
                "id": issue_id,
                "input": update_input
            }
        }

        response = requests.post(self.base_url, headers=self.headers, json=payload)
        response.raise_for_status()

        data = response.json()
        if "errors" in data:
            raise Exception(f"GraphQL errors: {data['errors']}")

        result = data["data"]["issueUpdate"]
        if not result["success"]:
            raise Exception("Issue update failed")

        return result["issue"]


