```python
import requests
import json

class UnraidAPIClient:
    """Client for interacting with Unraid GraphQL API"""

    def __init__(self, base_url, api_key):
        """
        Initialize the API client

        Args:
            base_url: The base URL of the Unraid server (e.g., "http://localhost:3000/graphql")
            api_key: API key for authentication
        """
        self.base_url = base_url
        self.headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}"
        }

    def _execute_graphql(self, query, variables=None):
        """
        Execute a GraphQL query or mutation

        Args:
            query: GraphQL query/mutation string
            variables: Optional variables dictionary

        Returns:
            Response data from the API
        """
        payload = {
            "query": query,
            "variables": variables or {}
        }

        response = requests.post(
            self.base_url,
            headers=self.headers,
            json=payload
        )
        response.raise_for_status()

        result = response.json()

        if "errors" in result:
            raise Exception(f"GraphQL Error: {result['errors']}")

        return result.get("data")

    def create_system_alert(self, title, subject, description, link=None):
        """
        Create a new system alert notification

        Args:
            title: Alert title (event name)
            subject: Alert subject
            description: Detailed alert description
            link: Optional link for more information

        Returns:
            Created notification object
        """
        mutation = """
        mutation CreateNotification($input: NotificationData!) {
            createNotification(input: $input) {
                id
                title
                subject
                description
                importance
                timestamp
                formattedTimestamp
            }
        }
        """

        variables = {
            "input": {
                "title": title,
                "subject": subject,
                "description": description,
                "importance": "ALERT"
            }
        }

        if link:
            variables["input"]["link"] = link

        data = self._execute_graphql(mutation, variables)
        return data["createNotification"]

    def rename_container_group(self, folder_id, new_name):
        """
        Change the display name of a Docker folder (container group)

        Args:
            folder_id: ID of the Docker folder to rename
            new_name: New display name for the folder

        Returns:
            Updated organizer structure
        """
        mutation = """
        mutation RenameDockerFolder($folderId: String!, $newName: String!) {
            renameDockerFolder(folderId: $folderId, newName: $newName) {
                version
                views {
                    id
                    name
                    rootId
                    flatEntries {
                        id
                        type
                        name
                        parentId
                        depth
                        position
                    }
                }
            }
        }
        """

        variables = {
            "folderId": folder_id,
            "newName": new_name
        }

        data = self._execute_graphql(mutation, variables)
        return data["renameDockerFolder"]


def main():
    """Main function demonstrating the API usage"""

    # Initialize client with placeholder credentials
    api_key = "YOUR_API_KEY"
    base_url = "http://your-unraid-server/graphql"

    client = UnraidAPIClient(base_url, api_key)

    # Task 1: Send a new system alert
    print("Creating system alert notification...")
    alert = client.create_system_alert(
        title="Critical System Event",
        subject="Disk Temperature Warning",
        description="Server disk temperature has exceeded safe threshold. Immediate attention required.",
        link="http://your-unraid-server/disks"
    )
    print(f"Alert created successfully: {alert['id']}")
    print(f"  Title: {alert['title']}")
    print(f"  Importance: {alert['importance']}")
    print(f"  Timestamp: {alert['formattedTimestamp']}")

    # Task 2: Rename container group
    print("\nRenaming container group...")
    folder_id = "existing_folder_id"  # Replace with actual folder ID
    new_name = "Production Services"

    result = client.rename_container_group(folder_id, new_name)
    print(f"Container group renamed successfully!")
    print(f"  Organizer version: {result['version']}")
    print(f"  Number of views: {len(result['views'])}")

    # Find and display the renamed folder in the views
    for view in result['views']:
        for entry in view['flatEntries']:
            if entry['id'] == folder_id:
                print(f"  Confirmed new name: {entry['name']}")


if __name__ == "__main__":
    main()
```

### Notes

