import requests
import json

class UnraidAPIClient:
    """Client for interacting with Unraid GraphQL API"""

    def __init__(self, base_url, api_key):
        """
        Initialize the API client

        Args:
            base_url: The base URL of the Unraid server (e.g., "http://localhost:3000/graphql")
            api_key: API key for authentication
        """
        self.base_url = base_url
        self.headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}"
        }

    def _execute_graphql(self, query, variables=None):
        """
        Execute a GraphQL query or mutation

        Args:
            query: GraphQL query/mutation string
            variables: Optional variables dictionary

        Returns:
            Response data from the API
        """
        payload = {
            "query": query,
            "variables": variables or {}
        }

        response = requests.post(
            self.base_url,
            headers=self.headers,
            json=payload
        )
        response.raise_for_status()

        result = response.json()

        if "errors" in result:
            raise Exception(f"GraphQL Error: {result['errors']}")

        return result.get("data")

    def create_system_alert(self, title, subject, description, link=None):
        """
        Create a new system alert notification

        Args:
            title: Alert title (event name)
            subject: Alert subject
            description: Detailed alert description
            link: Optional link for more information

        Returns:
            Created notification object
        """
        mutation = """
        mutation CreateNotification($input: NotificationData!) {
            createNotification(input: $input) {
                id
                title
                subject
                description
                importance
                timestamp
                formattedTimestamp
            }
        }
        """

        variables = {
            "input": {
                "title": title,
                "subject": subject,
                "description": description,
                "importance": "ALERT"
            }
