import requests
import json

# Configuration
SHOPIFY_GRAPHQL_ENDPOINT = "https://your-store.myshopify.com/api/graphql"
CUSTOMER_ACCESS_TOKEN = "YOUR_CUSTOMER_ACCESS_TOKEN"  # Session credential
STOREFRONT_ACCESS_TOKEN = "YOUR_STOREFRONT_ACCESS_TOKEN"  # API authentication

class ShopifyCartManager:
    def __init__(self, graphql_endpoint, storefront_token, customer_token):
        self.endpoint = graphql_endpoint
        self.headers = {
            "Content-Type": "application/json",
            "X-Shopify-Storefront-Access-Token": storefront_token
        }
        self.customer_token = customer_token

    def execute_graphql(self, query, variables=None):
        """Execute a GraphQL query or mutation"""
        payload = {"query": query}
        if variables:
            payload["variables"] = variables

        response = requests.post(
            self.endpoint,
            headers=self.headers,
            json=payload
        )
        response.raise_for_status()
        return response.json()

    def get_customer_profile(self):
        """Retrieve the currently signed-in shopper's profile details"""
        query = """
        query getCustomer($customerAccessToken: String!) {
          customer(customerAccessToken: $customerAccessToken) {
            id
            email
            firstName
            lastName
            displayName
            phone
            acceptsMarketing
            defaultAddress {
              id
              address1
              address2
              city
              province
              provinceCode
              country
              countryCode
              zip
              phone
            }
            createdAt
            updatedAt
          }
        }
        """

        variables = {
            "customerAccessToken": self.customer_token
        }

        result = self.execute_graphql(query, variables)

        if "errors" in result:
            raise Exception(f"GraphQL errors: {result['errors']}")

        return result["data"]["customer"]

    def create_checkout_with_products(self, email, line_items):
        """
        Create a new shopping cart (checkout) with selected products

        Args:
            email: Customer email
            line_items: List of dicts with 'variantId' and 'quantity'
                       Example: [{"variantId": "gid://shopify/ProductVariant/123", "quantity": 2}]
        """
        mutation = """
        mutation checkoutCreate($input: CheckoutCreateInput!) {
          checkoutCreate(input: $input) {
            checkout {
              id
              webUrl
              createdAt
              email
              lineItems(first: 50) {
                edges {
                  node {
                    id
                    title
                    quantity
                    variant {
                      id
                      title
                      price {
                        amount
                        currencyCode
                      }
                      product {
                        id
                        title
                      }
                    }
                  }
                }
              }
              subtotalPrice {
                amount
                currencyCode
              }
              totalPrice {
                amount
                currencyCode
              }
              totalTax {
                amount
                currencyCode
              }
            }
            userErrors {
              field
              message
            }
          }
        }
        """

        variables = {
            "input": {
                "email": email,
                "lineItems": line_items
            }
        }

        result = self.execute_graphql(mutation, variables)

        if "errors" in result:
            raise Exception(f"GraphQL errors: {result['errors']}")

        payload = result["data"]["checkoutCreate"]

        if payload["userErrors"]:
            raise Exception(f"User errors: {payload['userErrors']}")

        return payload["checkout"]

    def associate_customer_to_checkout(self, checkout_id):
        """Associate the authenticated customer with a checkout"""
        mutation = """
        mutation checkoutCustomerAssociate($checkoutId: ID!, $customerAccessToken: String!) {
          checkoutCustomerAssociate(
            checkoutId: $checkoutId
            customerAccessToken: $customerAccessToken
          ) {
            checkout {
              id
              customer {
                id
                email
                firstName
                lastName
              }
            }
            userErrors {
              field
              message
            }
          }
        }
        """

        variables = {
            "checkoutId": checkout_id,
            "customerAccessToken": self.customer_token
        }

        result = self.execute_graphql(mutation, variables)

        if "errors" in result:
            raise Exception(f"GraphQL errors: {result['errors']}")

        payload = result["data"]["checkoutCustomerAssociate"]

        if payload["userErrors"]:
            raise Exception(f"User errors: {payload['userErrors']}")

        return payload["checkout"]


def main():
    # Initialize the cart manager
    cart_manager = ShopifyCartManager(
        graphql_endpoint=SHOPIFY_GRAPHQL_ENDPOINT,
        storefront_token=STOREFRONT_ACCESS_TOKEN,
        customer_token=CUSTOMER_ACCESS_TOKEN
    )

    # Step 1: Retrieve customer profile
    print("Fetching customer profile...")
    customer_profile = cart_manager.get_customer_profile()
    print(f"Customer: {customer_profile['displayName']}")
    print(f"Email: {customer_profile['email']}")
    print(f"Customer ID: {customer_profile['id']}")

    if customer_profile['defaultAddress']:
        print(f"Default Address: {customer_profile['defaultAddress']['city']}, "
              f"{customer_profile['defaultAddress']['province']}")

    # Step 2: Create a new checkout with products
    print("\nCreating new shopping cart...")
    line_items = [
        {
            "variantId": "gid://shopify/ProductVariant/12345678901234",
            "quantity": 2
        },
        {
            "variantId": "gid://shopify/ProductVariant/98765432109876",
            "quantity": 1
        }
    ]

    checkout = cart_manager.create_checkout_with_products(
        email=customer_profile['email'],
        line_items=line_items
    )

    print(f"Checkout created: {checkout['id']}")
    print(f"Checkout URL: {checkout['webUrl']}")
    print(f"Total Price: {checkout['totalPrice']['amount']} "
          f"{checkout['totalPrice']['currencyCode']}")

    print("\nLine Items:")
    for edge in checkout['lineItems']['edges']:
        item = edge['node']
        print(f"  - {item['title']} (Qty: {item['quantity']}) - "
              f"{item['variant']['price']['amount']} "
              f"{item['variant']['price']['currencyCode']}")

    # Step 3: Associate customer with checkout
    print("\nAssociating customer with checkout...")
    updated_checkout = cart_manager.associate_customer_to_checkout(checkout['id'])
    print(f"Customer {updated_checkout['customer']['email']} "
          f"associated with checkout {updated_checkout['id']}")

    print("\n✓ Task completed successfully!")
    print(f"Shopping cart ready at: {checkout['webUrl']}")


if __name__ == "__main__":
    main()
```

### Notes

1. **Authentication Requirements**: 
   - The API requires two types of tokens:
     - `X-Shopify-Storefront-Access-Token`: A Storefront API access token for API authentication
     - `customerAccessToken`: The session credential obtained when the customer logs in (from `customerAccessTokenCreate` mutation)

2. **Product Variant IDs**:
   - Line items require `variantId` in the Shopify GID format: `gid://shopify/ProductVariant/{numeric_id}`
   - The `quantity` field is required and must be an integer

3. **Pagination**: 
   - The API uses cursor-based pagination (indicated by `@pg` in the schema)
   - Line items return edges/nodes structure typical of GraphQL connections
   - First parameter limits the number of items returned (e.g., `lineItems(first: 50)`)

4. **Error Handling**:
   - GraphQL can return errors at two levels: top-level `errors` array and field-specific `userErrors`
   - Always check both before proceeding with the response data

5. **Checkout vs Cart**:
   - In Shopify's Storefront API, "Checkout" is the cart object
   - The `webUrl` field provides a direct link for the customer to complete their purchase

6. **Customer Association**:
   - The `checkoutCustomerAssociate` mutation links the authenticated customer to the checkout
   - This enables features like saved addresses and order history tracking

7. **Money Type**:
   - All monetary values use the `Money` type with `amount` (string) and `currencyCode` fields
   - Amount is returned as a string to preserve decimal precision

