# GraphQL client helper
def execute_graphql(query, variables=None):
    """Execute a GraphQL query against the Shopify Storefront API."""
    headers = {
        "Content-Type": "application/json",
        "X-Shopify-Storefront-Access-Token": STOREFRONT_ACCESS_TOKEN
    }

    payload = {"query": query}
    if variables:
        payload["variables"] = variables

    response = requests.post(
        SHOPIFY_STOREFRONT_URL,
        headers=headers,
        json=payload
    )
    response.raise_for_status()
    return response.json()


def register_customer(email, password, first_name=None, last_name=None, phone=None, accepts_marketing=False):
    """
    Register a new customer account on the storefront.

    Args:
        email: Customer's email address (required)
        password: Customer's password (required)
        first_name: Customer's first name (optional)
        last_name: Customer's last name (optional)
        phone: Customer's phone number (optional)
        accepts_marketing: Whether customer accepts marketing emails (optional, default False)

    Returns:
        dict: Customer data if successful, None if failed
    """
    mutation = """
    mutation customerCreate($input: CustomerCreateInput!) {
      customerCreate(input: $input) {
        customer {
          id
          email
          firstName
          lastName
          phone
          acceptsMarketing
          createdAt
        }
        userErrors {
          field
          message
        }
      }
    }
    """

    variables = {
        "input": {
            "email": email,
            "password": password
        }
    }

    # Add optional fields if provided
    if first_name:
        variables["input"]["firstName"] = first_name
    if last_name:
        variables["input"]["lastName"] = last_name
    if phone:
        variables["input"]["phone"] = phone
    if accepts_marketing:
        variables["input"]["acceptsMarketing"] = accepts_marketing

    result = execute_graphql(mutation, variables)

