import requests
import json

class GitHubGraphQLClient:
    """
    Client for interacting with GitHub's GraphQL API.
    This class provides methods to search for developers/projects and retrieve user profiles.
    """

    def __init__(self, api_key):
        """
        Initialize the GitHub GraphQL client.

        Args:
            api_key (str): GitHub personal access token
        """
        self.api_url = "https://api.github.com/graphql"
        self.headers = {
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json"
        }

    def search_developers(self, keyword, limit=10):
        """
        Search for developers matching a keyword.

        Args:
            keyword (str): Search keyword (e.g., "python developer", "machine learning")
            limit (int): Maximum number of results to return (default: 10)

        Returns:
            dict: Search results containing user information
        """
        query = """
        query SearchDevelopers($keyword: String!, $first: Int!) {
            search(query: $keyword, type: USER, first: $first) {
                userCount
                nodes {
                    ... on User {
                        login
                        name
                        avatarUrl
                        bio
                        company
                        location
                        url
                        followers {
                            totalCount
                        }
                        repositories(first: 5, orderBy: {field: STARGAZERS, direction: DESC}) {
                            totalCount
                            nodes {
                                name
                                stargazerCount
                            }
                        }
                    }
                }
            }
        }
        """

        variables = {
            "keyword": keyword,
            "first": limit
        }

        payload = {
            "query": query,
            "variables": variables
        }

        response = requests.post(self.api_url, headers=self.headers, json=payload)
        response.raise_for_status()
        return response.json()

    def search_projects(self, keyword, limit=10):
        """
        Search for repositories/projects matching a keyword.

        Args:
            keyword (str): Search keyword (e.g., "web scraper", "chatbot")
            limit (int): Maximum number of results to return (default: 10)

        Returns:
            dict: Search results containing repository information
        """
        query = """
        query SearchProjects($keyword: String!, $first: Int!) {
            search(query: $keyword, type: REPOSITORY, first: $first) {
                repositoryCount
                nodes {
                    ... on Repository {
                        name
                        nameWithOwner
                        description
                        url
                        stargazerCount
                        forkCount
                        primaryLanguage {
                            name
                        }
                        owner {
                            login
                        }
                    }
                }
            }
        }
        """

        variables = {
            "keyword": keyword,
            "first": limit
        }

        payload = {
            "query": query,
            "variables": variables
        }

        response = requests.post(self.api_url, headers=self.headers, json=payload)
        response.raise_for_status()
        return response.json()

    def get_user_profile(self, username):
        """
        Get a developer's public profile by username.

        Args:
            username (str): GitHub username/login

        Returns:
            dict: User profile information
        """
        query = """
        query GetUserProfile($login: String!) {
            user(login: $login) {
                login
                name
                bio
                bioHTML
                avatarUrl
                company
                companyHTML
                location
                email
                websiteUrl
                twitterUsername
                pronouns
                createdAt
                updatedAt
                isHireable
                isBountyHunter
                isCampusExpert
                isDeveloperProgramMember
                isEmployee
                isGitHubStar
                followers {
                    totalCount
                }
                following {
                    totalCount
                }
                repositories(first: 10, orderBy: {field: STARGAZERS, direction: DESC}) {
                    totalCount
                    nodes {
                        name
                        description
                        stargazerCount
                        forkCount
                        primaryLanguage {
                            name
                        }
                    }
                }
                gists {
                    totalCount
                }
                issues {
                    totalCount
                }
                pullRequests {
                    totalCount
                }
                contributionsCollection {
                    contributionCalendar {
                        totalContributions
                    }
                }
                socialAccounts(first: 10) {
                    nodes {
                        provider
                        displayName
                        url
                    }
                }
                status {
                    message
                    emoji
                }
            }
        }
        """

        variables = {
            "login": username
        }

        payload = {
            "query": query,
            "variables": variables
        }

        response = requests.post(self.api_url, headers=self.headers, json=payload)
        response.raise_for_status()
        return response.json()


def main():
    """
    Main function demonstrating the usage of the GitHubGraphQLClient.
    """
    # Initialize client with API key (use placeholder for this exercise)
    api_key = "YOUR_API_KEY"
    client = GitHubGraphQLClient(api_key)

    # Example 1: Search for developers by keyword
    print("=" * 60)
    print("Searching for developers matching 'python machine learning'...")
    print("=" * 60)

    developer_results = client.search_developers("python machine learning", limit=5)

    if 'data' in developer_results and 'search' in developer_results['data']:
        search_data = developer_results['data']['search']
        print(f"\nTotal developers found: {search_data['userCount']}")
        print("\nTop results:")

        for idx, user in enumerate(search_data.get('nodes', []), 1):
            print(f"\n{idx}. {user.get('name', 'N/A')} (@{user['login']})")
            print(f"   Bio: {user.get('bio', 'No bio')}")
            print(f"   Company: {user.get('company', 'N/A')}")
            print(f"   Location: {user.get('location', 'N/A')}")
            print(f"   Followers: {user.get('followers', {}).get('totalCount', 0)}")
            print(f"   Profile: {user['url']}")

    # Example 2: Search for projects/repositories by keyword
    print("\n" + "=" * 60)
    print("Searching for projects matching 'web scraper'...")
    print("=" * 60)

    project_results = client.search_projects("web scraper", limit=5)

    if 'data' in project_results and 'search' in project_results['data']:
        search_data = project_results['data']['search']
        print(f"\nTotal repositories found: {search_data['repositoryCount']}")
        print("\nTop results:")

        for idx, repo in enumerate(search_data.get('nodes', []), 1):
            print(f"\n{idx}. {repo['nameWithOwner']}")
            print(f"   Description: {repo.get('description', 'No description')}")
            print(f"   Stars: {repo.get('stargazerCount', 0)}")
            print(f"   Language: {repo.get('primaryLanguage', {}).get('name', 'N/A')}")
            print(f"   URL: {repo['url']}")

    # Example 3: Get a specific developer's public profile
    print("\n" + "=" * 60)
    print("Fetching profile for user 'octocat'...")
    print("=" * 60)

    profile_result = client.get_user_profile("octocat")

    if 'data' in profile_result and 'user' in profile_result['data']:
        user = profile_result['data']['user']

        print(f"\nUsername: {user['login']}")
        print(f"Name: {user.get('name', 'N/A')}")
        print(f"Bio: {user.get('bio', 'No bio')}")
        print(f"Company: {user.get('company', 'N/A')}")
        print(f"Location: {user.get('location', 'N/A')}")
        print(f"Email: {user.get('email', 'N/A')}")
        print(f"Website: {user.get('websiteUrl', 'N/A')}")
        print(f"Twitter: {user.get('twitterUsername', 'N/A')}")
        print(f"Hireable: {user.get('isHireable', False)}")
        print(f"Created: {user.get('createdAt', 'N/A')}")
        print(f"\nStats:")
        print(f"  Followers: {user.get('followers', {}).get('totalCount', 0)}")
        print(f"  Following: {user.get('following', {}).get('totalCount', 0)}")
        print(f"  Public Repos: {user.get('repositories', {}).get('totalCount', 0)}")
        print(f"  Public Gists: {user.get('gists', {}).get('totalCount', 0)}")
        print(f"  Total Contributions: {user.get('contributionsCollection', {}).get('contributionCalendar', {}).get('totalContributions', 0)}")

        print(f"\nTop Repositories:")
        repos = user.get('repositories', {}).get('nodes', [])
        for idx, repo in enumerate(repos[:5], 1):
            print(f"  {idx}. {repo['name']} - ⭐ {repo.get('stargazerCount', 0)}")

        social_accounts = user.get('socialAccounts', {}).get('nodes', [])
        if social_accounts:
            print(f"\nSocial Accounts:")
            for account in social_accounts:
                print(f"  {account['provider']}: {account['url']}")

        status = user.get('status')
        if status and status.get('message'):
            print(f"\nStatus: {status.get('emoji', '')} {status['message']}")


if __name__ == "__main__":
    main()
```

### Notes

1. **Authentication Required**: This API requires a valid GitHub Personal Access Token. Create one at https://github.com/settings/tokens with appropriate scopes (typically `read:user`, `public_repo`)

2. **GraphQL API**: This is GitHub's GraphQL API v4. All requests go to a single endpoint (`https://api.github.com/graphql`) with different query structures

3. **Rate Limits**: 
   - Authenticated requests: 5,000 points per hour
   - Each query costs a certain number of points based on complexity
   - Use the `rateLimit` query to check remaining quota

4. **Search Query Syntax**: The search query supports GitHub's search qualifiers:
   - `type:user` - Search only users
   - `location:seattle` - Filter by location
   - `followers:>1000` - Filter by follower count
   - Combine keywords: `"python developer" location:london`

5. **Pagination**: The API uses cursor-based pagination. Use `first`/`after` or `last`/`before` parameters with `PageInfo` to navigate results

6. **Field Selection**: GraphQL allows you to request only the fields you need. The queries above request comprehensive profile data, but you can customize them based on your needs

7. **Error Handling**: Always check for `errors` field in the response. GraphQL can return partial data with errors

8. **Alternative Search Types**:
   - `REPOSITORY` - Search for projects/repositories
   - `ISSUE` - Search for issues
   - `DISCUSSION` - Search for discussions

