import requests
import json

# Configuration
SHOPIFY_DOMAIN = "your-store.myshopify.com"
GRAPHQL_ENDPOINT = f"https://{SHOPIFY_DOMAIN}/api/2024-01/graphql.json"
CUSTOMER_ACCESS_TOKEN = "YOUR_CUSTOMER_ACCESS_TOKEN"

# Product variant IDs to add to cart
PRODUCTS_TO_ADD = [
    {"variantId": "gid://shopify/ProductVariant/12345678901234", "quantity": 2},
    {"variantId": "gid://shopify/ProductVariant/98765432109876", "quantity": 1}
]


def execute_graphql_query(query, variables=None):
    """Execute a GraphQL query against Shopify Storefront API"""
    headers = {
        "Content-Type": "application/json",
        "X-Shopify-Storefront-Access-Token": "YOUR_STOREFRONT_ACCESS_TOKEN"
    }

    payload = {"query": query}
    if variables:
        payload["variables"] = variables

    response = requests.post(GRAPHQL_ENDPOINT, json=payload, headers=headers)
    response.raise_for_status()
    return response.json()


def get_customer_profile(customer_access_token):
    """Retrieve customer profile details using session credential"""
    query = """
    query GetCustomer($customerAccessToken: String!) {
      customer(customerAccessToken: $customerAccessToken) {
        id
        email
        firstName
        lastName
        displayName
        phone
        defaultAddress {
          id
          address1
          address2
          city
          province
          provinceCode
          country
          countryCode
          zip
          phone
        }
        createdAt
        updatedAt
        acceptsMarketing
      }
    }
    """

    variables = {"customerAccessToken": customer_access_token}
    result = execute_graphql_query(query, variables)

    if "errors" in result:
        raise Exception(f"GraphQL errors: {result['errors']}")

    return result["data"]["customer"]


def create_checkout_with_products(line_items):
    """Create a new checkout (shopping cart) with selected products"""
    mutation = """
    mutation CreateCheckout($input: CheckoutCreateInput!) {
      checkoutCreate(input: $input) {
        checkout {
          id
          webUrl
          lineItems(first: 50) {
            edges {
              node {
                id
                title
                quantity
                variant {
                  id
                  title
                  price
                  sku
                }
              }
            }
          }
          subtotalPrice
          totalTax
          totalPrice
          currencyCode
          createdAt
        }
        userErrors {
          field
          message
        }
      }
    }
    """

    variables = {
        "input": {
            "lineItems": line_items
        }
    }

    result = execute_graphql_query(mutation, variables)

    if "errors" in result:
        raise Exception(f"GraphQL errors: {result['errors']}")

    payload = result["data"]["checkoutCreate"]

    if payload["userErrors"]:
        raise Exception(f"User errors: {payload['userErrors']}")

    return payload["checkout"]


def associate_customer_to_checkout(checkout_id, customer_access_token):
    """Associate the signed-in customer with the checkout"""
    mutation = """
    mutation AssociateCustomer($checkoutId: ID!, $customerAccessToken: String!) {
      checkoutCustomerAssociate(
        checkoutId: $checkoutId,
        customerAccessToken: $customerAccessToken
      ) {
        checkout {
          id
          customer {
            id
            email
            firstName
            lastName
          }
        }
        userErrors {
          field
          message
        }
      }
    }
    """

    variables = {
        "checkoutId": checkout_id,
        "customerAccessToken": customer_access_token
    }

    result = execute_graphql_query(mutation, variables)

    if "errors" in result:
        raise Exception(f"GraphQL errors: {result['errors']}")

    payload = result["data"]["checkoutCustomerAssociate"]

    if payload["userErrors"]:
        raise Exception(f"User errors: {payload['userErrors']}")

    return payload["checkout"]


def main():
    """Main execution flow"""
    print("=" * 60)
    print("Shopify Shopper Profile & Cart Creation")
    print("=" * 60)

    # Step 1: Retrieve customer profile
    print("\n[1] Retrieving customer profile...")
    try:
        customer = get_customer_profile(CUSTOMER_ACCESS_TOKEN)
        print(f"✓ Customer found: {customer['displayName']} ({customer['email']})")
        print(f"  Customer ID: {customer['id']}")
        if customer['defaultAddress']:
            addr = customer['defaultAddress']
            print(f"  Default Address: {addr['city']}, {addr['province']}, {addr['country']}")
    except Exception as e:
        print(f"✗ Error retrieving customer: {e}")
        return

    # Step 2: Create checkout with products
    print("\n[2] Creating checkout with products...")
    try:
        checkout = create_checkout_with_products(PRODUCTS_TO_ADD)
        print(f"✓ Checkout created: {checkout['id']}")
        print(f"  Subtotal: {checkout['subtotalPrice']} {checkout['currencyCode']}")
        print(f"  Total: {checkout['totalPrice']} {checkout['currencyCode']}")
        print(f"  Items in cart: {len(checkout['lineItems']['edges'])}")
        for edge in checkout['lineItems']['edges']:
            item = edge['node']
            print(f"    - {item['title']} (Qty: {item['quantity']})")
        print(f"  Checkout URL: {checkout['webUrl']}")
    except Exception as e:
        print(f"✗ Error creating checkout: {e}")
        return

    # Step 3: Associate customer with checkout
    print("\n[3] Associating customer with checkout...")
    try:
        updated_checkout = associate_customer_to_checkout(
            checkout['id'],
            CUSTOMER_ACCESS_TOKEN
        )
        print(f"✓ Customer associated successfully")
        print(f"  Customer: {updated_checkout['customer']['firstName']} "
              f"{updated_checkout['customer']['lastName']}")
        print(f"  Email: {updated_checkout['customer']['email']}")
    except Exception as e:
        print(f"✗ Error associating customer: {e}")
        return

    print("\n" + "=" * 60)
    print("Shopping cart ready for purchase!")
    print(f"Share this link with customer: {checkout['webUrl']}")
    print("=" * 60)


if __name__ == "__main__":
    main()
```

### Notes

1. **Authentication**: This implementation requires two types of credentials:
   - `customerAccessToken`: A session credential obtained when a customer logs in (via `customerAccessTokenCreate` mutation). This token is required for the `customer` query and `checkoutCustomerAssociate` mutation.
   - Storefront Access Token: A public token for your Shopify store to access the Storefront API.

2. **Product Variant IDs**: Product variant IDs must be in the global ID format: `gid://shopify/ProductVariant/{numeric_id}`. These can be obtained by querying products first using the `shop.products` query.

3. **Error Handling**: The Shopify GraphQL API returns two types of errors:
   - `errors`: GraphQL-level errors (malformed queries, authentication issues)
   - `userErrors`: Business logic errors (invalid product IDs, out of stock items, etc.)

4. **Checkout vs Cart**: In Shopify's Storefront API, a "checkout" is equivalent to a shopping cart. The checkout object contains line items and can be completed to create an order.

5. **Session Management**: The `customerAccessToken` expires after a period (returned in the `expiresAt` field when created). Use `customerAccessTokenRenew` mutation to extend the session.

6. **Rate Limits**: Shopify Storefront API has rate limits based on cost per query. The `customer` query and mutations used here are relatively low-cost operations.

7. **Alternative Flow**: You can also create a checkout with line items and customer association in separate steps, or include the customer's email in the `CheckoutCreateInput` to pre-fill checkout information without explicit association.

