    print(f"Company: {profile['company']}")
    print(f"Website: {profile['websiteUrl']}")
    print(f"Created: {profile['createdAt']}")
    print(f"Followers: {profile['followers']['totalCount']}")
    print(f"Following: {profile['following']['totalCount']}")
    print(f"Public Repositories: {profile['repositories']['totalCount']}")

    print("\nContributions:")
    contributions = profile['contributionsCollection']
    print(f"- Commits: {contributions['totalCommitContributions']}")
    print(f"- Issues: {contributions['totalIssueContributions']}")
    print(f"- Pull Requests: {contributions['totalPullRequestContributions']}")
    print(f"- PR Reviews: {contributions['totalPullRequestReviewContributions']}")

    print("\nTop Repositories:")
    for repo in profile['repositories']['nodes'][:5]:
        lang = repo['primaryLanguage']['name'] if repo['primaryLanguage'] else "N/A"
        print(f"\n- {repo['name']} ({lang})")
        print(f"  {repo['description']}")
        print(f"  Stars: {repo['stargazerCount']}, Forks: {repo['forkCount']}")


if __name__ == "__main__":
    main()
