```python
import requests
import json

class GitHubGraphQLClient:
    """Client for interacting with GitHub's GraphQL API"""

    def __init__(self, token):
        """
        Initialize the GitHub GraphQL client

        Args:
            token: GitHub personal access token
        """
        self.base_url = "https://api.github.com/graphql"
        self.headers = {
            "Authorization": f"Bearer {token}",
            "Content-Type": "application/json"
        }

    def execute_query(self, query, variables=None):
        """
        Execute a GraphQL query

        Args:
            query: GraphQL query string
            variables: Dictionary of variables for the query

        Returns:
            Response data from the API
        """
        payload = {"query": query}
        if variables:
            payload["variables"] = variables

        response = requests.post(
            self.base_url,
            headers=self.headers,
            json=payload
        )
        response.raise_for_status()
        return response.json()

    def search_developers(self, keyword, limit=10):
        """
        Search for developers matching a keyword

        Args:
            keyword: Search keyword (e.g., "python developer", "machine learning")
            limit: Maximum number of results to return

        Returns:
            List of developers matching the search criteria
        """
        query = """
        query SearchDevelopers($searchQuery: String!, $first: Int!) {
            search(query: $searchQuery, type: USER, first: $first) {
                userCount
                edges {
                    node {
                        ... on User {
                            login
                            name
                            avatarUrl
                            bio
                            location
                            company
                            email
                            websiteUrl
                            followers {
                                totalCount
                            }
                        }
                    }
                }
            }
        }
        """

        variables = {
            "searchQuery": keyword,
            "first": limit
        }

        result = self.execute_query(query, variables)
        return result["data"]["search"]

    def search_projects(self, keyword, limit=10):
        """
        Search for projects/repositories matching a keyword

        Args:
            keyword: Search keyword (e.g., "web framework python", "react components")
            limit: Maximum number of results to return

        Returns:
            List of repositories matching the search criteria
        """
        query = """
        query SearchProjects($searchQuery: String!, $first: Int!) {
            search(query: $searchQuery, type: REPOSITORY, first: $first) {
                repositoryCount
                edges {
                    node {
                        ... on Repository {
                            name
                            nameWithOwner
                            description
                            url
                            stargazerCount
                            forkCount
                            primaryLanguage {
                                name
                            }
                            owner {
                                login
                            }
                            createdAt
                            updatedAt
                        }
                    }
                }
            }
        }
        """

        variables = {
            "searchQuery": keyword,
            "first": limit
        }

        result = self.execute_query(query, variables)
        return result["data"]["search"]

    def get_user_profile(self, username):
        """
        Get a developer's public profile by username

        Args:
            username: GitHub username/login

        Returns:
            Detailed user profile information
        """
        query = """
        query GetUserProfile($login: String!) {
            user(login: $login) {
                login
                name
                avatarUrl
                bio
                bioHTML
                company
                companyHTML
                location
                email
                websiteUrl
                twitterUsername
                createdAt
                updatedAt
                followers {
                    totalCount
                }
                following {
                    totalCount
                }
                repositories(first: 10, orderBy: {field: STARGAZERS, direction: DESC}) {
                    totalCount
                    nodes {
                        name
                        description
                        stargazerCount
                        forkCount
                        url
                        primaryLanguage {
                            name
                        }
                    }
                }
                contributionsCollection {
                    totalCommitContributions
                    totalIssueContributions
                    totalPullRequestContributions
                    totalPullRequestReviewContributions
                }
                pullRequests(first: 1) {
                    totalCount
                }
                issues(first: 1) {
                    totalCount
                }
            }
        }
        """

        variables = {
            "login": username
        }

        result = self.execute_query(query, variables)
        return result["data"]["user"]


def main():
